/* ===== ai.js ===== */
/* ============================================
   MyHealth — Enemy AI Strategy (M2b 打磨 B)
   敌人决策：选技能 + 选目标（替代纯随机）。
   策略：残血集火、治疗优先、Boss 保留大招、连招意识。
   纯逻辑，依赖 skill.js / battle-group.js。
   ============================================ */

/* 决策上下文辅助 */
/* v2.14.20（阶段 C）：两个入口都改用 `attackable()` 单源判据 —— 敌方 AI 的选靶池里
   永远不会出现 `_untargetable` 的单位（多队战斗＝玩家）；普通战斗无标记，行为不变。 */
function aliveOpponents(gb, actor) {
  return (actor.side === 'ally' ? gb.enemies : gb.allies).filter(function(u){ return attackable(u); });
}
function aliveAllies(gb, actor) {
  return (actor.side === 'ally' ? gb.allies : gb.enemies).filter(function(u){ return attackable(u); });
}

/* 目标评分：残血优先、低防优先、治疗者优先 */
function scoreTarget(t) {
  var score = 0;
  var hpPct = t.hp / Math.max(1, t.base.hp);
  // 残血优先（可斩杀）
  if (hpPct < 0.25) score += 30;
  else if (hpPct < 0.5) score += 15;
  // 低防优先
  var def = t.base.def || 0;
  if (def < 10) score += 10;
  // 有治疗/增益技能的优先
  if (t.skills && t.skills.some(function(s){ var d = SKILLS[s]; return d && d.type === 'support'; })) score += 8;
  // 攻击高（威胁大）优先
  if (t.base.atk >= 50) score += 5;
  return score + battleRnd() * 5;  // 少量随机避免完全确定
}

/* 选目标：评分最高（嘲讽者强制） */
function aiPickTarget(gb, actor, skillDef) {
  // 嘲讽强制
  var taunters = aliveOpponents(gb, actor).filter(function(u){ return u._taunting; });
  if (taunters.length) return taunters[0];

  var pool = aliveOpponents(gb, actor);
  if (!pool.length) return null;

  // 全体技能 → 返回全部（由调用方处理）
  if (skillDef && (skillDef.target === 'all')) return pool;

  // 辅助治疗类 → 我方残血
  if (skillDef && (skillDef.target === 'ally1' || skillDef.target === 'self')) {
    var allies = aliveAllies(gb, actor);
    if (!allies.length) return null;
    allies.sort(function(a, b){ return (a.hp / a.base.hp) - (b.hp / b.base.hp); });
    return allies[0];  // 最残血的我方
  }

  // 攻击类 → 评分最高
  pool.sort(function(a, b){ return scoreTarget(b) - scoreTarget(a); });
  return pool[0];
}

/* v2.14.8（作者规格 1「**Boss 不应施放 lastword**」）：
   Boss 的**技能候选里**去掉「遗言」——**不从技能池删除**（SKILLS / group-levels 的
   敌方技能池一字未改，普通精英仍然带得出、放得出），也不算「获得但不许放」：
   技能仍在单位自己的 `skills` 列表里（详情页/日志可见），只是 AI 永不把它选出来。
   为什么是「生成时不给」的反面：技能编成由 group-levels.js 的确定性技能流决定
   （test-talent-fixation 的种子哨兵锁着它），在建场处过滤会把整条随机流打乱；
   而且「Boss 带遗言但永不发动」对玩家是可解释的行为（图鉴/详情仍能看到该技能）。
   判据：`_tier === 'boss'`（enemy.js 的 createEnemyUnit 写入），
   兜底也认 `tags` 里的 'boss'（tags 与 _tier 同源写入，防快照/手搓单位缺字段）。 */
function aiIsBoss(actor) {
  if (!actor) return false;
  if (actor._tier === 'boss') return true;
  return Object.prototype.toString.call(actor.tags) === '[object Array]' && actor.tags.indexOf('boss') >= 0;
}

/* 选技能：策略化（不纯随机）
   优先级：能斩杀残血 → 治疗残血 → Boss 大招（低血触发）→ 冷却就绪的强技能 → 随机 */
function aiPickSkill(gb, actor) {
  var usable = usableSkills(actor);
  /* 🔴 v2.14.8：Boss 的候选列表剔除「遗言」。
     落点是**候选入口**而不是最后那条分支 —— `lastword` 有 3 条进入路径：
       ③ 低血大招（`sid === 'doom' || sid === 'lastword'`）
       ④ 70% 取最强 / 30% 随机取一个（`sorted[0]` / `sorted[随机]`）
     只在其中一条上拦必定漏掉另外两条（只在 ③ 拦：满血 Boss 仍会从 ④ 摸到遗言）。
     过滤后**可能变空**（Boss 只带了 lastword 一个技能）→ 原样返回 null，
     调用方 groupUnitTurn 会走普攻，与「没有可用技能」的既有路径完全一致。 */
  if (aiIsBoss(actor)) {
    usable = usable.filter(function (sid) { return sid !== 'lastword'; });
  }
  if (!usable.length) return null;
  var opponents = aliveOpponents(gb, actor);
  var myAllies = aliveAllies(gb, actor);
  var myHpPct = actor.hp / Math.max(1, actor.base.hp);

  // 1. 可斩杀残血敌人的攻击技能（优先）
  var killable = opponents.find(function(t){ return t.hp / t.base.hp < 0.3; });
  if (killable) {
    var atkSkills = usable.filter(function(sid){
      var d = SKILLS[sid];
      return d && d.type === 'attack';
    });
    if (atkSkills.length) return atkSkills[0];
  }

  // 2. 治疗残血队友（辅助治疗技能）
  var hurtAlly = myAllies.find(function(t){ return t.hp / t.base.hp < 0.4; });
  if (hurtAlly) {
    var healSkills = usable.filter(function(sid){
      var d = SKILLS[sid];
      return d && d.type === 'support' && (d.target === 'ally1');
    });
    if (healSkills.length) return healSkills[0];
  }

  // 3. Boss 低血时放大招（高伤害或特级负面）
  if (myHpPct < 0.35 && actor._tier === 'boss') {
    var ultSkills = usable.filter(function(sid){
      var d = SKILLS[sid];
      if (!d || d.type !== 'attack') return false;
      return (d.power || 0) >= 300;
    });
    if (ultSkills.length) return ultSkills[0];
    // 特级负面（末日）也算大招
    var doomSkill = usable.find(function(sid){ return sid === 'doom' || sid === 'lastword'; });
    if (doomSkill) return doomSkill;
  }

  // 4. 强技能优先（power 高/先制度高），否则随机
  var sorted = usable.slice().sort(function(a, b){
    var da = SKILLS[a], db = SKILLS[b];
    var pa = (da && da.power) || 0, pb = (db && db.power) || 0;
    var pra = (da && da.priority) || 0, prb = (db && db.priority) || 0;
    return (pb + prb * 20) - (pa + pra * 20);
  });
  // 70% 用最强，30% 随机（避免太机械）
  if (battleRnd() < 0.7) return sorted[0];
  return sorted[Math.floor(battleRnd() * sorted.length)];
}

/* 集成：替换 battle-group 里的 pickSkill/selectTargets 调用 */
function aiDecide(gb, actor) {
  var skillId = aiPickSkill(gb, actor);
  var skillDef = skillId ? (SKILLS[skillId] || null) : null;
  var target = aiPickTarget(gb, actor, skillDef);
  return { skillId: skillId, target: target, skillDef: skillDef };
}

;
/* ===== challenge.js ===== */
/* ============================================
   MyHealth — Hidden Challenge (隐藏挑战召唤)
   ============================================ */

/* ========== v2.2 WP-H8：掉落产出倍率（唯一可调常量） ==========
   来源 doc/2.2 修改-补充.md 原文：
     「提升宝珠碎片的掉落数量（变为3倍）」
     「提升炼化石产出（变为2倍）」
     「提升灵能产出（变为2倍）」
   三类 = **宝珠碎片 orbShard ×3** / **炼化石（普通 refineNormal + 高级 refineHigh）×2** / **灵能 spirit ×2**。
   ⚠️ 倍率只在这一处定义：新掉落点一律走 applyDropMult() / applyDropMults()，别在掉落点另写数字。
   ✅ 覆盖范围（v2.2 WP-H8 补线后）：本文件的挑战掉落（基础 + 每周次数奖励）+ 敌群胜利的**基础掉落**
      （game-render.js 的 groupVictoryReward，v2.2.22 起改走 applyDropMults()）。
      ⚠️ 有意不覆盖：宠物天赋「幸运口袋」那几笔天赋独立产出（见 game-render.js 该处注释）。 */
var DROP_MULT = { orbShard: 3, refineNormal: 2, refineHigh: 2, spirit: 2 };

function dropMultFor(type){ return DROP_MULT[type] || 1 }

/* 单条数量套倍率：向下取整（数量本为整数，取整只防浮点尾数） */
function applyDropMult(type, n){
  var v=(typeof n==='number'&&isFinite(n))?n:0
  return Math.floor(v*dropMultFor(type))
}

/* 对一批掉落条目统一套倍率（纯函数：返回新数组，不改入参） */
function applyDropMults(drops){
  return (drops||[]).map(function(d){
    return { type:d.type, n:applyDropMult(d.type,d.n), lucky:d.lucky }
  })
}

/* ========== v2.4.10：属性奖励阈值（唯一可调常量） ==========
   伤害 → 月度属性奖励的除数（除数越小越慷慨）：
     ⚔️ 攻击 = floor(dmg / atk)   🛡️ 防御 = floor(dmg / def)
     ❤️ 生命 = floor(dmg / hp) × hpStep

   历史沿革：
     v2.4.9 及以前 = 2250 / 3375 / 675（hpStep 3）
     v2.4.10 起倒计时由 **8~12s 缩为 6~8s**（点击量约 −30%）→ 三档等比 **×0.7**
     目的：让「同等手速拿到的属性奖励」与缩短前持平，本次改动只适配新时长、不改强度。

   ⚠️ def / hp 是**小数**，这是刻意的：0.7 倍后 3375→2362.5、675→472.5 本就不是整数。
      取整会引入约 0.1% 的**系统性**偏差，随伤害放大（实测 hp 在大伤害下比不取整多漂 15 点）；
      保留小数后偏差只剩「取整边界效应」最多 1 步（hp = 3 点），量级差 5 倍。
      同时保住了原设计里「生命奖励速率 = 攻击的 10 倍」（3/472.5 = 1/157.5 = 10/1575）。
      回归测试：`scripts/test-challenge-tuning.js`（35 断言，含两个反证）。

   ⚠️ 只在本文件 endChallenge() 一处消费。以后调奖励只改这里，别在结算点另写数字。 */
var CH_REWARD_DIV = { atk: 1575, def: 2362.5, hp: 472.5, hpStep: 3 };

/* ========== v2.4.10：倒计时区间（唯一可调常量，秒） ==========
   普通挑战 = [min, max] 均匀随机；热血 buff 'timeBonus' 在此区间上叠加
   「基础时间锁高档 70%~100%」再 ×1.4（见 startHiddenChallenge）。
   ⚠️ 文案（挑战预览的「倒计时 X-Y 秒」）必须与此处同步，别两处各写一个数。 */
var CH_DUR_MIN = 6, CH_DUR_MAX = 8;

/* ========== SUMMON LOGIC ========== */
function getChallenge(){
  var c=store.get('challenge')||{}
  // 字段归一化：兼容旧数据/缺字段/NaN污染，防止 undefined+1=NaN 传播
  var num=function(v,d){return(typeof v==='number'&&isFinite(v))?v:d}
  var str=function(v,d){return(typeof v==='string')?v:d}
  c.summonedDate=str(c.summonedDate,'')
  c.seasonBonus=(c.seasonBonus&&typeof c.seasonBonus==='object'&&!Array.isArray(c.seasonBonus))?c.seasonBonus:{atk:0,def:0,hp:0}
  c.seasonBonus.atk=num(c.seasonBonus.atk,0)
  c.seasonBonus.def=num(c.seasonBonus.def,0)
  c.seasonBonus.hp=num(c.seasonBonus.hp,0)
  c.todayUsed=num(c.todayUsed,0)
  c.useDate=str(c.useDate,'')
  c.weekDays=Array.isArray(c.weekDays)?c.weekDays:[]
  c.weekKey=str(c.weekKey,'')
  c.hotBuffUsed=!!c.hotBuffUsed
  c.pendingChallenge=!!c.pendingChallenge
  c.lastRewardDate=str(c.lastRewardDate,'')
  c.madeUpDate=str(c.madeUpDate,'')
  c.madeUpUsed=num(c.madeUpUsed,0)
  c.pendingIsMakeup=!!c.pendingIsMakeup
  c.history=Array.isArray(c.history)?c.history:[]
  // v2.2 WP-H4：每月记录归档（monthly = { 'YYYY-MM': {...} }；monthlyKey = 当前归档月键，写法同 pet-store.js）
  c.monthlyKey=str(c.monthlyKey,'')
  c.monthly=(c.monthly&&typeof c.monthly==='object'&&!Array.isArray(c.monthly))?c.monthly:{}
  c.lastSeasonMonth=str(c.lastSeasonMonth,'')
  // 清理 v1.9.1 时代遗留字段（已无使用）
  if(c.todayFailCount!==undefined){delete c.todayFailCount}
  if(c.failDate!==undefined){delete c.failDate}
  return c
}
function saveChallenge(c){store.set('challenge',c||{})}

/* 召唤成功率阶梯：used=今日已失败次数。
   第1次10%，每失败一次+15%（10/25/40/55），第5次起保底80%，第6次起必成 */
function summonRate(used){
  var u=(typeof used==='number'&&isFinite(used))?Math.max(0,used):0
  if(u>=5)return 100
  if(u===4)return 80
  return Math.min(100,10+u*15)
}

/* Daily reset: new day resets todayUsed （同时兜底修复 NaN 污染） */
function checkChallengeDailyReset(){
  var c=getChallenge()
  var t=today()
  var dirty=false
  if(c.useDate!==t){c.useDate=t;c.todayUsed=0;c.madeUpUsed=0;dirty=true}
  // 结构修复：todayUsed 非有限数 → 0
  if(typeof c.todayUsed!=='number'||!isFinite(c.todayUsed)){c.todayUsed=0;dirty=true}
  if(typeof c.seasonBonus!=='object'||!c.seasonBonus){c.seasonBonus={atk:0,def:0,hp:0};dirty=true}
  // 清理 v1.9.1 遗留字段（todayFailCount/failDate）
  if(c.todayFailCount!==undefined){delete c.todayFailCount;dirty=true}
  if(c.failDate!==undefined){delete c.failDate;dirty=true}
  if(dirty)saveChallenge(c)
}

/* Week key = Monday's date of current week */
function getWeekKey(){
  var n=new Date(),d=n.getDay()
  var m=new Date(n);m.setDate(n.getDate()+(d===0?-6:1-d))
  return toDate(m)
}

/* Today's volume from strength entries */
function getVolumeFor(dateStr){
  var strE=((store.get('strength')||{entries:[]}).entries)||[]
  var filtered=strE.filter(function(e){return e.date===dateStr})
  return sumVolume(filtered,getExerciseMap())
}
function getTodayVolume(){return getVolumeFor(today())}

/* Can summon? Each 100kg grants 1 attempt; ladder 10/25/40/55/80/100 via summonRate().
   容量实时对齐：训练记录被删除导致总次数缩水时，撤销未开始的召唤资格并封顶已用次数
   双池设计（v2.0.2）：
   - 今日池 floor(今日容量/100)：成功 → summonedDate=今日（每日 1 次守卫）
   - 补召池 floor(昨日容量/100)：昨日漏召（仅 1 天）→ 顺延至今日；成功 → madeUpDate=昨日，
     **不占用今日名额**，今日仍可正常召唤（否则每周成功次数会少一次）
   - 优先消耗补召池（当日过期）；失败按消耗池记账，阶梯概率按今日总尝试次数 */
function canSummon(){
  checkChallengeDailyReset()
  var c=getChallenge()
  var vol=getVolumeFor(today())
  if(typeof vol!=='number'||!isFinite(vol))vol=0
  var yd=new Date();yd.setDate(yd.getDate()-1)
  var yKey=toDate(yd)
  var yVol=getVolumeFor(yKey)
  if(typeof yVol!=='number'||!isFinite(yVol))yVol=0
  var usedYesterday=(c.history||[]).some(function(h){return h&&h.date===yKey})||(c.weekDays||[]).indexOf(yKey)>=0
  var madeUp=c.madeUpDate===yKey
  var todayPool=Math.floor(vol/100)
  var borrowPool=(!usedYesterday&&!madeUp)?Math.floor(yVol/100):0
  var madeUpUsed=(typeof c.madeUpUsed==='number'&&isFinite(c.madeUpUsed))?c.madeUpUsed:0
  var remainBorrow=Math.max(0,borrowPool-madeUpUsed)
  var remainToday=(c.summonedDate===today())?0:Math.max(0,todayPool-c.todayUsed)
  var total=todayPool+borrowPool
  // 容量回撤守卫：pending 资格所依赖的训练记录被删除（total < 已用数，含成功那一次）→ 同步撤销
  if(c.pendingChallenge&&c.summonedDate!==today()&&total<c.todayUsed){
    c.pendingChallenge=false
    c.todayUsed=Math.max(0,Math.min(c.todayUsed,total))
    saveChallenge(c)
    toast('⚠️ 检测到训练记录被删除，今日召唤资格已同步撤销','e')
  }
  // 已召唤成功但还没开始（稍后再说/刷新后恢复）
  if(c.pendingChallenge)return{can:true,pending:true,reason:'已召唤成功，等待开始挑战'}
  var rate=summonRate(c.todayUsed+madeUpUsed)
  if(remainBorrow>0&&remainToday>0)return{can:true,mode:'both',rate:rate,total:total,used:c.todayUsed,vol:vol,borrowed:borrowPool,remainBorrow:remainBorrow,remainToday:remainToday,yVol:yVol}
  if(remainBorrow>0)return{can:true,mode:'makeup',rate:rate,total:total,used:c.todayUsed,vol:vol,borrowed:borrowPool,remainBorrow:remainBorrow,remainToday:0,yVol:yVol}
  if(remainToday>0)return{can:true,mode:'normal',rate:rate,total:total,used:c.todayUsed,vol:vol,borrowed:0,remainBorrow:0,remainToday:remainToday,yVol:yVol}
  if(c.summonedDate===today()&&!madeUp&&yVol>=100)return{can:false,total:total,used:c.todayUsed,vol:vol,borrowed:0,yVol:yVol,reason:'今日已召唤成功；昨日虽漏召但补召资格不可用'}
  return{can:false,total:total,used:c.todayUsed,vol:vol,borrowed:0,yVol:yVol,reason:'今日训练容量 '+Math.round(vol)+'kg（昨日无可用补召资格），每 100kg 获得 1 次召唤机会'}
}

/* Attempt summon */
/* 结算状态转换（v2.0.7）：按挑战类型记账
   - 正常召唤：summonedDate=今日（每日 1 次守卫）
   - 补召（pendingIsMakeup）：madeUpDate 已在召唤时记账，**不写 summonedDate**
     → 今日名额保留，补召后当天仍可正常召唤 */
function applyChallengeSettle(c, isMakeup){
  c.pendingChallenge=false
  if(isMakeup){
    c.madeUpDate=toDate((function(){var d=new Date();d.setDate(d.getDate()-1);return d})())
  }else{
    c.summonedDate=today()
  }
  c.pendingIsMakeup=false
  c.lastRewardDate=today()
}

/* Attempt summon */
function attemptSummon(){
  var info=canSummon()
  if(!info.can){toast(info.reason,'e');return}
  var c=getChallenge()
  var rate=isFinite(info.rate)?info.rate:10
  var roll=Math.random()*100
  var consumeBorrow=info.remainBorrow>0   // 优先消耗补召池（当日过期）
  if(roll<rate){
    // Success! Mark pending, show challenge preview (NOT started yet)
    c.pendingChallenge=true
    if(consumeBorrow){
      // 补召成功：记 madeUpDate/madeUpUsed + pendingIsMakeup 标记（结算时不占今日名额）
      c.madeUpDate=toDate((function(){var d=new Date();d.setDate(d.getDate()-1);return d})())
      c.madeUpUsed=(typeof c.madeUpUsed==='number'&&isFinite(c.madeUpUsed)?c.madeUpUsed:0)+1
      c.pendingIsMakeup=true
      toast('🔮 补召成功！补上昨日的挑战，点击开始！','s')
    }else{
      c.summonedDate=today()
      c.todayUsed=(typeof c.todayUsed==='number'&&isFinite(c.todayUsed)?c.todayUsed:0)+1
      c.pendingIsMakeup=false
      toast('🔮 召唤成功！点击开始挑战！','s')
    }
    saveChallenge(c)
    showChallengePreview()
  }else{
    // Failure — attempt used (按消耗池记账), rate climbs for next try
    if(consumeBorrow)c.madeUpUsed=(typeof c.madeUpUsed==='number'&&isFinite(c.madeUpUsed)?c.madeUpUsed:0)+1
    else c.todayUsed=(typeof c.todayUsed==='number'&&isFinite(c.todayUsed)?c.todayUsed:0)+1
    saveChallenge(c)
    var newRate=summonRate(c.todayUsed+c.madeUpUsed)
    var remain=isFinite(info.total)?Math.max(0,info.total-(c.todayUsed+c.madeUpUsed)):'?'
    toast('❌ 召唤失败！下次成功率 '+newRate+'%（剩 '+remain+' 次）','e')
    renderSummonPanel()
  }
}

/* ========== SUMMON PANEL UI ========== */
/* Debug: 屏幕诊断 — FAB 与抽屉由 debug.js 全局提供；此处内嵌诊断块
   由 window.__debugChallenge 控制（DebugPanel 抽屉「挑战」分区开关） */
function toggleChDebug(){window.__debugChallenge=!window.__debugChallenge;renderSummonPanel();if(window.DebugPanel)window.DebugPanel.refresh()}
/* 组装充足诊断数据 */
function chDebugBlock(info,strVol,c,branch){
  var out=''
  if(window.__debugChallenge){
    var entries=((store.get('strength')||{entries:[]}).entries)||[]
    var todayE=entries.filter(function(e){return e.date===today()})
    var exMap=getExerciseMap()
    var lines=['[branch: '+branch+']','today='+today()]
    lines.push('strVol='+strVol)
    lines.push('canSummon='+JSON.stringify(info))
    lines.push('total='+Math.floor(strVol/100)+' used='+(info&&isFinite(info.used)?info.used:'?')+' rate='+(info&&isFinite(info.rate)?info.rate:'?'))
    lines.push('todayEntries='+todayE.length)
    todayE.forEach(function(e,i){
      var ex=exMap[e.exercise]||{}
      var w=e.eqWeight!=null?e.eqWeight:(e.weight||0)
      var n=e.actualReps||(e.duration?e.duration:0)
      var r=(ex.ratio!=null?ex.ratio:100)
      var vol=Math.round(w*n*(r/100))
      lines.push('  ['+i+'] '+e.exercise+' w='+w+' eq='+(e.eqWeight!=null?e.eqWeight:'-')+' n='+n+' ratio='+r+' vol='+vol)
    })
    lines.push('challenge='+JSON.stringify(c))
    out+='<div style="margin-top:4px;padding:8px;background:#1a1a1a;border:1px dashed #ef4444;border-radius:8px;font-size:var(--fs-3xs);color:#94a3b8;line-height:1.6;white-space:pre-wrap;word-break:break-all">'+lines.join('\n')+'</div>'
  }
  return out
}
/* 挂载调试块 + 绑定开关（每个分支统一调用） */
function mountSummonExtras(el,info,strVol,c,branch){
  var hb=document.getElementById('chHistoryBtn')
  if(hb)hb.addEventListener('click',function(){showChallengeHistory()})
}
function renderSummonPanel(){
  var el=document.getElementById('summonPanel')
  if(!el)return
  var info=canSummon()
  var strVol=getTodayVolume()
  var triggers=Math.floor(strVol/100)
  var c0=getChallenge()
  // pending 挑战不受当日容量限制（可能昨天召唤成功今天才打开）
  // 今日容量不足但可借用昨日未用资格（info.can=true）→ 落到下方正常召唤卡片
  if(strVol<100&&!info.can&&!c0.pendingChallenge){
    el.innerHTML=chDebugBlock(info,strVol,c0,'vol100')
    mountSummonExtras(el,info,strVol,c0,'vol100')
    return
  }
  
  var c=getChallenge()
  if(c.summonedDate===today()){
    // Already played today
    var bonus=c.seasonBonus||{atk:0,def:0,hp:0};
    var rewarded=c.lastRewardDate===today()
    // v2.0.8: 补召误锁恢复——v2.0.6 前补召结算误写 summonedDate，这类存档需开放恢复入口
    var yd=new Date();yd.setDate(yd.getDate()-1)
    var madeUpLocked=c.madeUpDate===toDate(yd)
    var showRecover=!rewarded||madeUpLocked
    el.innerHTML='<div class="summon-card done">'
      +'<div class="summon-title">⚡ 今日隐藏挑战已完成</div>'
      +'<div class="summon-info">'+(madeUpLocked?'昨日补召已完成，可恢复今日召唤资格':'明日继续，每月 1 号重置奖励')+'</div>'
      +(bonus.atk+bonus.def+bonus.hp>0?'<div class="summon-bonus">本月已获得: ⚔️+'+bonus.atk+' 🛡️+'+bonus.def+' ❤️+'+bonus.hp+'</div>':'')
      +(info.can&&info.mode==='makeup'?'<button class="summon-btn" id="makeupBtn" style="margin-top:8px;background:rgba(var(--success-rgb),.1);border-color:var(--green);color:var(--green);padding:10px;font-size:var(--fs-sm)">🔁 补召昨日挑战（剩 '+info.remainBorrow+' 次，不占今日名额）</button>':'')
      +(showRecover?'<button class="summon-btn" id="summonBtn" style="margin-top:8px;background:rgba(var(--danger-rgb),.1);border-color:var(--red);color:var(--red);padding:10px;font-size:var(--fs-sm)">↩️ '+(madeUpLocked?'补召已结算？恢复今日召唤资格':'今日未完成？恢复挑战')+'</button>':'')
      +'<button class="summon-btn" id="chHistoryBtn" style="margin-top:8px;background:var(--bg3);color:var(--text2);border:var(--bw) solid var(--bd);padding:10px;font-size:var(--fs-sm)">📜 历史召唤成绩</button>'
      +'</div>'
      +chDebugBlock(info,strVol,c,'done')
    mountSummonExtras(el,info,strVol,c,'done')
    var br=document.getElementById('summonBtn')
    if(br)br.addEventListener('click',function(){
      // 旧 bug 锁死恢复：今天被标记完成但从未结算奖励 → 解锁并回到召唤
      var c2=getChallenge()
      c2.summonedDate=''
      c2.pendingChallenge=false
      saveChallenge(c2)
      toast('已恢复今日挑战资格，重新召唤吧 🔮','s')
      renderSummonPanel()
    })
    var mk=document.getElementById('makeupBtn')
    if(mk)mk.addEventListener('click',function(){attemptSummon()})
    return
  }
  // 已召唤成功但没开始（稍后再说/刷新后）→ 恢复预览
  if(c.pendingChallenge){
    el.innerHTML='<div class="summon-card">'
      +'<div class="summon-title">🔮 已召唤成功！</div>'
      +'<div class="summon-info">挑战尚未开始，随时可以继续</div>'
      +'<button class="summon-btn" id="summonBtn">⚔️ 开始挑战</button>'
      +'</div>'
      +chDebugBlock(info,strVol,c,'pending')
    mountSummonExtras(el,info,strVol,c,'pending')
    var b2=document.getElementById('summonBtn')
    if(b2)b2.addEventListener('click',function(){showChallengePreview()})
    return
  }
  // 不可召唤（次数用完/其他）→ 显示原因卡片而非可召唤面板
  if(!info.can){
    el.innerHTML='<div class="summon-card done">'
      +'<div class="summon-title">🔮 隐藏挑战</div>'
      +'<div class="summon-info">'+(info.reason||'今日不可召唤')+'</div>'
      +(isFinite(info.total)?'<div class="summon-info" style="font-size:var(--fs-3xs);color:var(--text3)">今日容量 <b style="color:var(--orange)">'+Math.round(info.vol||0)+'kg</b> · 可用 '+Math.max(0,isFinite(info.used)?info.total-info.used:0)+'/'+info.total+' 次（已用 '+(isFinite(info.used)?info.used:0)+'）</div>':'')
      +'<button class="summon-btn" id="chHistoryBtn" style="margin-top:8px;background:var(--bg3);color:var(--text2);border:var(--bw) solid var(--bd);padding:10px;font-size:var(--fs-sm)">📜 历史召唤成绩</button>'
      +'</div>'
      +chDebugBlock(info,strVol,c,'cannot')
    mountSummonExtras(el,info,strVol,c,'cannot')
    return
  }
  
  var rate=info.rate||10
  var rateColor=rate>=50?'var(--green)':rate>=30?'var(--orange)':'var(--yellow)'
  var totalN=isFinite(info.total)?info.total:'?'
  var usedN=isFinite(info.used)?info.used:0
  var remain=isFinite(info.remainToday)?(info.remainToday+info.remainBorrow):'?'
  var hotHtml=renderHotBuffHint(c)
  el.innerHTML='<div class="summon-card">'
    +'<div class="summon-title">🔮 隐藏挑战</div>'
    +'<div class="summon-info">今日训练容量 <b>'+Math.round(strVol)+'kg</b> · 召唤机会 <b>'+remain+'/'+totalN+'</b> 次（每 100kg +1 次）</div>'
    +(info.borrowed>0?'<div class="summon-info" style="color:var(--green)">🔁 昨日补召机会剩 '+info.remainBorrow+'/'+info.borrowed+' 次（昨日 '+Math.round(info.yVol||0)+'kg · 优先消耗 · 不占今日名额）</div>':'')
    +'<div class="summon-rate-wrap">'
    +  '<div style="font-size:var(--fs-2xs);color:var(--text3);margin-bottom:4px">本次召唤成功率（第 '+(usedN+1)+' 次'+(usedN>=5?' · 必成 100%':usedN===4?' · 保底 80%':' · 基础 10%')+'）</div>'
    +  '<div class="summon-rate-bar"><div class="summon-rate-fill" style="width:'+rate+'%;background:'+rateColor+'"></div></div>'
    +  '<div style="text-align:center;font-weight:700;color:'+rateColor+';font-size:var(--fs-lg);margin-top:4px">'+rate+'%</div>'
    +'</div>'
    +hotHtml
    +'<button class="summon-btn" id="summonBtn">🔮 召唤</button>'
    +'<div style="font-size:var(--fs-3xs);color:var(--text3);text-align:center;margin-top:6px">成功率阶梯 10/25/40/55/80/100% · 每天最多成功召唤1次</div>'
    +'</div>'
    +'<button class="summon-btn" id="chHistoryBtn" style="margin-top:8px;background:var(--bg3);color:var(--text2);border:var(--bw) solid var(--bd);padding:10px;font-size:var(--fs-sm)">📜 历史召唤成绩</button>'
    +chDebugBlock(info,strVol,c,'normal')
  var btn=document.getElementById('summonBtn')
  if(btn)btn.addEventListener('click',attemptSummon)
  mountSummonExtras(el,info,strVol,c,'normal')
}

/* 热血 buff hint — 本周连续 3 天开启后，第 4 次开启附加热血 buff */
function renderHotBuffHint(c){
  var wk=getWeekKey()
  if(c.weekKey!==wk){c.weekKey=wk;c.weekDays=[];c.hotBuffUsed=false}
  var days=c.weekDays?c.weekDays.length:0
  if(c.hotBuffUsed)return''
  if(days>=5){
    return'<div class="summon-hot ready">🔥 热血 buff 已就绪！本次挑战随机获得：暴击率+55%·暴伤+35% / 暴伤+120%·暴击率+15% / 倒计时+40%·基础时间70~100%</div>'
  }
  if(days>=1){
    return'<div class="summon-hot">🔥 本周已挑战 '+days+' 次，累计 5 次解锁热血 buff！</div>'
  }
  return''
}

/* ========== HIDDEN CHALLENGE MINIGAME ========== */

/* Pick a random 热血 buff (weekly, once per week after 4 consecutive days) */
function pickHotBuff(){
  var buffs=['critRate','critDmg','timeBonus']
  return buffs[Math.floor(Math.random()*buffs.length)]
}
function hotBuffLabel(kind){
  return kind==='critRate'?'🔥 暴击率+55% · 暴击伤害+35%':kind==='critDmg'?'🔥 暴击伤害+120% · 暴击率+15%':'🔥 倒计时+40% · 基础时间70~100%'
}

/* Step 1: summon success → show challenge preview, wait for user to press 开始挑战 */
function showChallengePreview(){
  var old=document.getElementById('challengeModal')
  if(old)old.remove()
  var stats=getGameStats()
  var modal=openModal(null,'challengeModal',{noBackdrop:true})
  var h='<div class="modal-sheet wide">'
    +'<div class="modal-handle"></div>'
    +'<div class="modal-title">🔬 隐藏挑战</div>'
    +'<div class="ch-preview">'
    +  '<div class="ch-preview-title">召唤成功！</div>'
    +  '<div style="font-size:var(--fs-xs);color:var(--text3);margin-bottom:8px">倒计时 '+CH_DUR_MIN+'-'+CH_DUR_MAX+' 秒，疯狂点击攻击按钮造成伤害，伤害将转化为本月属性奖励。</div>'
    +  '<div class="ch-stats" style="grid-template-columns:1fr 1fr 1fr 1fr">'
    +    '<div class="ch-stat">⚔️ <b>'+stats.atk+'</b></div>'
    +    '<div class="ch-stat">👻 <b>'+(stats.soulAtk||0)+'</b></div>'
    +    '<div class="ch-stat">🛡️ <b>'+stats.def+'</b></div>'
    +    '<div class="ch-stat">🔮 <b>'+(stats.soulDef||0)+'</b></div>'
    +  '</div>'
    +  '<div style="font-size:var(--fs-2xs);color:var(--text3);text-align:center;margin:8px 0">基础伤害 = 攻×50% + 魂攻×150% + 防×100% + 魂防×100%，暴击 20%×1.5 倍</div>'
    +'</div>'
    +'<div class="modal-actions">'
    +  '<button class="m-btn-cancel" id="chLater">稍后再说</button>'
    +  '<button class="m-btn-save" id="chStart" style="flex:2">⚔️ 开始挑战</button>'
    +'</div>'
    +'</div>'
  modal.innerHTML=h
  document.getElementById('chLater').addEventListener('click',function(){modal.remove();renderSummonPanel();renderGame()})
  document.getElementById('chStart').addEventListener('click',function(){
    // 真正开始：保留 pending 资格（未结算前可重开），记录周天数，判定热血 buff
    var c=getChallenge()
    var wk=getWeekKey()
    if(c.weekKey!==wk){c.weekKey=wk;c.weekDays=[];c.hotBuffUsed=false}
    if(c.weekDays.indexOf(today())<0)c.weekDays.push(today())
    var hotBuff=null
    if(c.weekDays.length>=5&&!c.hotBuffUsed){
      hotBuff=pickHotBuff()
      c.hotBuffUsed=true
    }
    saveChallenge(c)
    modal.remove()
    startHiddenChallenge(hotBuff)
  })
  modal.addEventListener('click',function(e){if(e.target===e.currentTarget)modal.remove()})
}

/* Step 2: actual minigame — countdown + tap attack */
function startHiddenChallenge(hotBuff){
  var stats=getGameStats()
  var baseDur=CH_DUR_MIN+Math.floor(Math.random()*(CH_DUR_MAX-CH_DUR_MIN+1)) // 6-8 seconds（v2.4.10 前为 8-12）
  var duration=baseDur
  var critRate=0.20
  var critDmg=1.5   // 暴击伤害倍率制：基础 150%
  if(hotBuff==='critRate'){critRate=0.75;critDmg=1.85}  // 暴击率+55% 且 暴击伤害+35%
  if(hotBuff==='critDmg'){critRate=0.35;critDmg=2.7}   // 暴击伤害+120% 且 暴击率+15%
  if(hotBuff==='timeBonus'){
    // 倒计时+40%：基础时间锁定 70%~100% 高值区间（v2.4.10 起 = 7.4~8s）再 ×1.4 → 10~11s
    baseDur=CH_DUR_MIN+(CH_DUR_MAX-CH_DUR_MIN)*(0.7+Math.random()*0.3)
    duration=Math.round(baseDur*1.4)
  }
  // 热血 buff 触发：全屏金色闪光（特殊惊艳标识）
  /* v2.14.13：原来是 `background:radial-gradient(circle,rgba(251,191,36,.35),transparent 70%)`。
     v2.14.9 的守卫 `[style*="gradient"]{background-image:none!important}` 把它抽掉 → 闪光**完全不出现**
     （buff 反馈静默丢失）。扁平规范禁渐变，改为同色相的实色半透明铺底 + 原动画淡出，反馈仍然可见。 */
  if(hotBuff){
    var flash=document.createElement('div')
    flash.style='position:fixed;inset:0;z-index:70;pointer-events:none;background:rgba(251,191,36,.18);animation:hotFlash 1.2s ease-out forwards'
    document.body.appendChild(flash)
    setTimeout(function(){if(flash.parentNode)flash.remove()},1300)
  }
  var state={
    timeLeft:duration,
    duration:duration,
    totalDamage:0,
    hitCount:0,
    critCount:0,
    maxHit:0,
    timer:null,
    ticking:false,
    /* v2.17：本场结算的**唯一键**（宠物等级「本次伤害 × 1%」的幂等键）。
       开打时生成一次、整场不变 → 同一次结算被重复调用也不会重复发经验。 */
    runId:'ch_'+Date.now()+'_'+Math.random().toString(36).slice(2,8),
    critRate:critRate,
    critDmg:critDmg,
    hotBuff:hotBuff,
    perSecHits:[],     // hits per second (for result chart)
    playerAtk:stats.atk,
    playerSoulAtk:stats.soulAtk||0,
    playerDef:stats.def,
    playerSoulDef:stats.soulDef||0
  }
  
  var modal=openModal(null,'challengeModal',{noBackdrop:true})
  // v2.1.6：游戏进行中禁止任何"点背景隐藏"（app.js 的全局兜底也要跳过）。
  // 旧行为：点背景只摘 open class → 弹窗隐形、游戏继续跑、结果渲染进隐藏弹窗、
  // body 永久 position:fixed → 整页无法滚动。结束后在 endChallenge 里解除该标记。
  modal.dataset.noAutoClose='1'
  var h='<div class="modal-sheet wide">'
    +'<div class="modal-handle"></div>'
    +'<div class="modal-title">🔬 隐藏挑战</div>'
    +(hotBuff?'<div class="ch-hotbuff">'+hotBuffLabel(hotBuff)+'</div>':'')
    +'<div class="ch-timer-wrap">'
    +  '<div class="ch-timer" id="chTimer">'+duration+'s</div>'
    +  '<div class="ch-timer-bar-wrap"><div class="ch-timer-bar" id="chTimerBar" style="width:100%"></div></div>'
    +'</div>'
    +'<div class="ch-stats" id="chStats">'
    +  '<div class="ch-stat">⚔️ 攻 <b>'+state.playerAtk+'</b></div>'
    +  '<div class="ch-stat">👻 魂攻 <b>'+state.playerSoulAtk+'</b></div>'
    +  '<div class="ch-stat">🛡️ 防 <b>'+state.playerDef+'</b></div>'
    +  '<div class="ch-stat">🔮 魂防 <b>'+state.playerSoulDef+'</b></div>'
    +'</div>'
    +'<div class="ch-damage-display" id="chDamage">0</div>'
    +'<div class="ch-info" id="chInfo">'+(hotBuff==='timeBonus'?'倒计时延长 40%，坚持就是胜利！':'点击攻击造成伤害！')+'</div>'
    +'<button class="ch-attack-btn" id="chAttackBtn">⚔️ 攻击</button>'
    +'<div class="ch-hits" id="chHits"></div>'
    +'</div>'
  modal.innerHTML=h;void modal
  
  var attackBtn=document.getElementById('chAttackBtn')
  var timerEl=document.getElementById('chTimer')
  var timerBar=document.getElementById('chTimerBar')
  var damageEl=document.getElementById('chDamage')
  var infoEl=document.getElementById('chInfo')
  var hitsEl=document.getElementById('chHits')
  
  function doAttack(){
    if(state.ticking===false)return // game ended
    state.hitCount++
    // 记录当前秒点击数（用于结算曲线）
    var secIdx=state.duration-state.timeLeft
    if(secIdx>=0)state.perSecHits[secIdx]=(state.perSecHits[secIdx]||0)+1
    // 新公式: 基础伤害 = 攻×50% + 魂攻×150% + 防×100% + 魂防×100%，乘 random(0.5~1.5)
    var baseConst=state.playerAtk*0.5+state.playerSoulAtk*1.5+state.playerDef*1.0+state.playerSoulDef*1.0
    var rand=Math.random()*1+0.5 // 0.5~1.5
    var dmg=Math.round(baseConst*rand)
    var crit=false
    // 暴击倍率制: 基础率20%，暴击时伤害 × 暴击倍率
    if(Math.random()<state.critRate){
      crit=true
      state.critCount++
      dmg=Math.round(dmg*state.critDmg)
    }
    state.totalDamage+=dmg
    if(dmg>state.maxHit)state.maxHit=dmg
    
    // Visual feedback
    damageEl.textContent=state.totalDamage
    infoEl.innerHTML=(crit?'<span style="color:var(--yellow);font-weight:700">💥 暴击! +'+dmg+'</span>':'<span style="color:var(--orange)">+'+dmg+'</span>')
    // Hit log
    var hitDiv=document.createElement('div')
    hitDiv.className='ch-hit'+(crit?' crit':'')
    hitDiv.textContent=(crit?'💥':'⚔️')+' '+dmg+(crit?' (暴击)':'')
    hitsEl.insertBefore(hitDiv,hitsEl.firstChild)
    if(hitsEl.children.length>15)hitsEl.lastChild.remove()
    // Attack animation
    if(attackBtn){
      attackBtn.classList.remove('pulse')
      void attackBtn.offsetWidth
      attackBtn.classList.add('pulse')
    }
  }
  
  attackBtn.addEventListener('click',doAttack)
  
  // Touch-friendly: support rapid tapping
  attackBtn.addEventListener('touchstart',function(e){
    e.preventDefault()
    doAttack()
  })
  
  function endChallenge(){
    state.ticking=false
    if(state.timer){clearInterval(state.timer);state.timer=null}
    // v2.1.6：游戏已结束，解除"禁止点背景关闭"标记，让结算界面可正常关闭
    if(modal)delete modal.dataset.noAutoClose
    if(attackBtn)attackBtn.disabled=true
    // Calculate bonus: total damage → reward（阈值见文件顶部 CH_REWARD_DIV）
    var dmg=state.totalDamage
    var bonusAtk=Math.floor(dmg/CH_REWARD_DIV.atk)
    var bonusDef=Math.floor(dmg/CH_REWARD_DIV.def)
    var bonusHp=Math.floor(dmg/CH_REWARD_DIV.hp)*CH_REWARD_DIV.hpStep
    var c=getChallenge()
    c.seasonBonus.atk=(c.seasonBonus.atk||0)+bonusAtk
    c.seasonBonus.def=(c.seasonBonus.def||0)+bonusDef
    c.seasonBonus.hp=(c.seasonBonus.hp||0)+bonusHp
    applyChallengeSettle(c, c.pendingIsMakeup === true)
    // 记录历史成绩（含 buff）
    c.history=c.history||[]
    /* v2.2 WP-H4：旧存档一次性回填月份桶（幂等）—— 必须在 push 之前，
       否则新成绩会被「回填」与「合并」各计一次 */
    ensureChallengeMonthly(c)
    var _rec={
      date:today(),dmg:dmg,hits:state.hitCount,
      avgRate:state.duration>0?Math.round(state.hitCount/state.duration*10)/10:0,
      crits:state.critCount,maxHit:state.maxHit,
      atk:bonusAtk,def:bonusDef,hp:bonusHp,
      buff:state.hotBuff||null
    }
    c.history.push(_rec)
    if(c.history.length>50)c.history=c.history.slice(-50)
    recordChallengeMonth(c,_rec)
    saveChallenge(c)

    /* v2.17：**挑战额外宠物经验** —— 本次伤害 × 1%，每次结算发一次。
       幂等键 = 本场 `state.runId`（开打时生成），账本在 pet-store.js 的 levelLedger.challengeKeys。
       ⚠️ 放在材料掉落之前、独立一个 try：宠物系统未加载 / 出错都不影响挑战本身结算。 */
    try {
      if (typeof grantPetLevelChallengeExp === 'function') {
        var chLv = grantPetLevelChallengeExp(dmg, state.runId)
        state.petLevelExpReward = chLv
      }
    } catch (eLv) { console.warn('[challenge] 宠物等级经验发放失败（本场挑战成绩已正常保存）', eLv) }

    // 隐藏挑战材料掉落（基础掉落 + 每周次数额外奖励）
    try {
      if (typeof grantMaterial === 'function' && typeof getPetStore === 'function') {
        var matDrops = []      // 材料掉落
        var skillPoints = 0    // 技能点（额外奖励）
        var petEgg = null      // 宠物蛋（5次+奖励）
        var orbDrop = null     // v2.2 WP-A2：宝珠本体（挑战掉落）

        // 基础掉落（任何伤害）：
        matDrops.push({ type: 'nutrition', n: 5 + Math.floor(Math.random() * 6) })        // 5-10
        matDrops.push({ type: 'feed', n: 3 + Math.floor(Math.random() * 5) })             // 3-7
        matDrops.push({ type: 'refineNormal', n: 2 + Math.floor(Math.random() * 3) })     // 2-4
        matDrops.push({ type: 'refineHigh', n: Math.floor(Math.random() * 3) })           // 0-2
        matDrops.push({ type: 'spirit', n: 1 + Math.floor(Math.random() * 4) })           // 1-4
        matDrops.push({ type: 'orbShard', n: 4 + Math.floor(Math.random() * 5) })         // 4-8
        skillPoints += 20   // 基础掉落：技能点 20/次

        // 每周挑战次数额外奖励
        var d = getPetStore()
        d.challengeWeek = d.challengeWeek || {}
        var wkKey = 'W' + Math.ceil(new Date().getDate() / 7)
        d.challengeWeek[wkKey] = (d.challengeWeek[wkKey] || 0) + 1
        var weekCount = d.challengeWeek[wkKey]

        if (weekCount >= 2 && weekCount <= 3) {
          // 2-3 次：营养液 3-5(100%)，技能点 6-10(100%)，普通炼化石 2-3(100%)，高级炼化石 1-2(40%)
          matDrops.push({ type: 'nutrition', n: 3 + Math.floor(Math.random() * 3) })
          skillPoints += 6 + Math.floor(Math.random() * 5)
          matDrops.push({ type: 'refineNormal', n: 2 + Math.floor(Math.random() * 2) })
          if (Math.random() < 0.4) matDrops.push({ type: 'refineHigh', n: 1 + Math.floor(Math.random() * 2) })
        } else if (weekCount === 4) {
          // 4 次：营养液 4-8，技能点 8-12，普通炼化石 3-4，高级炼化石 1-2，饲料 2-4（全 100%）
          matDrops.push({ type: 'nutrition', n: 4 + Math.floor(Math.random() * 5) })
          skillPoints += 8 + Math.floor(Math.random() * 5)
          matDrops.push({ type: 'refineNormal', n: 3 + Math.floor(Math.random() * 2) })
          matDrops.push({ type: 'refineHigh', n: 1 + Math.floor(Math.random() * 2) })
          matDrops.push({ type: 'feed', n: 2 + Math.floor(Math.random() * 3) })
        } else if (weekCount >= 5) {
          // 5 次+：营养液 6-10，技能点 50-75，普通炼化石 4-5，高级炼化石 2-3，灵能 5-10，随机宠物蛋
          matDrops.push({ type: 'nutrition', n: 6 + Math.floor(Math.random() * 5) })
          skillPoints += 50 + Math.floor(Math.random() * 26)   // 50-75
          matDrops.push({ type: 'refineNormal', n: 4 + Math.floor(Math.random() * 2) })
          matDrops.push({ type: 'refineHigh', n: 2 + Math.floor(Math.random() * 2) })
          matDrops.push({ type: 'spirit', n: 5 + Math.floor(Math.random() * 6) })
          // 随机宠物蛋（未拥有的）
          try {
            var owned = d.pets.map(function (p) { return p.speciesId })
            var codex = listPetCodex().filter(function (id) { return owned.indexOf(id) === -1 })
            if (codex.length) {
              var sid = codex[Math.floor(Math.random() * codex.length)]
              var pet = createPet({ speciesId: sid, rarity: getPetCodex(sid).rarity, name: getPetCodex(sid).name })
              d.pets.push(pet)
              /* v2.2.29：带上 speciesId，结算面板据此显示宠物头像（原来只有名字） */
              petEgg = { name: pet.name, speciesId: sid }
            }
          } catch (e2) { console.warn('[challenge] 宠物蛋发放失败', e2) }
        }
        /* v2.2 WP-A2：**宝珠本体改为挑战掉落**（碎片只用于升级，不再合成宝珠）。
           每次胜利掉 1 颗：类型随机、品质按 ORB_DROP_RATES（R60% / SR25% / SSR12% / UR3%）。 */
        if (typeof rollOrbDrop === 'function') {
          var _orb = rollOrbDrop()
          if (_orb) {
            d.orbs = d.orbs || []
            d.orbs.push(_orb)
            orbDrop = _orb
          }
        }
        /* v2.2 WP-H8：三类掉落产出倍率统一在这里套用 ——
           宝珠碎片 ×3 / 炼化石（普通+高级）×2 / 灵能 ×2（倍率常量唯一来源 = 文件顶部 DROP_MULT）。
           ⚠️ 放在发放之前，让结果面板显示的数量与实际发放一致。 */
        matDrops = applyDropMults(matDrops)

        savePetStore(d)

        // 发放材料
        matDrops.forEach(function (dd) { grantMaterial(dd.type, dd.n) })
        // 发放技能点
        if (skillPoints > 0 && typeof getSkillState === 'function') {
          var ss = getSkillState()
          ss.points += skillPoints
          ss.totalEarned += skillPoints
          saveSkillState(ss)
        }
        // 供结果面板显示
        state.matReward = matDrops
        state.skillPointReward = skillPoints
        state.petEggReward = petEgg
        state.orbReward = orbDrop
      }
    } catch (e) { /* 材料系统未启用时忽略 */ }
    
    // Show result (enhanced: reward detail + per-second tap chart)
    var avgRate=state.duration>0?(state.hitCount/state.duration).toFixed(1):'0'
    var h2='<div class="ch-result">'
      +'<div class="ch-result-title">🏆 挑战结束</div>'
      +'<div class="ch-result-stats">'
      +  '<div>⚔️ 总伤害: <b>'+dmg+'</b></div>'
      +  '<div>🎯 命中: <b>'+state.hitCount+'</b> 次 · 平均 <b>'+avgRate+'</b> 次/秒</div>'
      +  '<div>💥 暴击: <b>'+state.critCount+'</b> 次</div>'
      +  '<div>🥇 最强一击: <b>'+state.maxHit+'</b></div>'
      +'</div>'
      +'<div class="ch-reward">'
      +  '<div style="font-weight:700;margin-bottom:6px">🎁 本月属性奖励（月度重置）</div>'
      +  '<div class="ch-reward-info">'      +(bonusAtk>0?'  <span style="color:var(--orange)">⚔️ +'+bonusAtk+'</span>':'')
      +(bonusDef>0?'  <span style="color:var(--blue)">🛡️ +'+bonusDef+'</span>':'')
      +(bonusHp>0?'  <span style="color:var(--green)">❤️ +'+bonusHp+'</span>':'')
      +(bonusAtk+bonusDef+bonusHp===0?'  <span style="color:var(--text3)">伤害不足，未获得奖励</span>':'')
      +  '</div>'
      +'</div>'
      +'<div class="ch-reward">'
      +  '<div style="font-weight:700;margin-bottom:6px">📦 材料掉落</div>'
      +  '<div class="ch-reward-info">'
      +((state.matReward && state.matReward.length) ? state.matReward.map(function(d){
          var names={nutrition:'🧪 营养液',feed:'🍖 饲料',spirit:'✨ 灵能',refineNormal:'🪨 炼化石',refineHigh:'💎 高炼石',orbShard:'🔮 宝珠碎片'};
          return '<span style="margin-right:8px">'+(names[d.type]||d.type)+' <b style="color:var(--green)">+'+d.n+'</b></span>';
        }).join('') : '<span style="color:var(--text3)">—</span>')
      +(state.skillPointReward > 0 ? '<div style="margin-top:4px">💠 技能点 <b style="color:var(--blue)">+'+state.skillPointReward+'</b>（本周 '+weekCount+' 次额外奖励）</div>' : '')
      +(state.petEggReward ? '<div style="margin-top:4px;display:flex;align-items:center;gap:6px">'
        + ((typeof petIconHtml === 'function') ? petIconHtml(state.petEggReward.speciesId, 32) : '')
        + '🥚 宠物蛋 <b style="color:var(--orange)">'+state.petEggReward.name+'</b></div>' : '')
      /* v2.15：宝珠结算也带图标（与库存 / 槽位同一入口 orbIconHtml，缺模块时回退 🔮）。
         ⚠️ challenge.js 比 pet-ui.js 先加载，但结算面板是运行时渲染，届时全局函数已就绪；
            仍保留 typeof 守卫，与上方 petEggReward 的 petIconHtml 同一手法。 */
      +(state.orbReward ? '<div style="margin-top:4px;display:flex;align-items:center;gap:6px">'
        + ((typeof orbIconHtml === 'function') ? orbIconHtml(state.orbReward.type, 32) : '🔮')
        + ' 宝珠 <b style="color:var(--purple)">'+((ORB_TYPES[state.orbReward.type]||{}).name||state.orbReward.type)+'（'+state.orbReward.rarity+' · +'+(typeof orbPct==='function'?orbPct(state.orbReward):'?')+'%）</b></div>' : '')
      +  '</div>'
      +'</div>'
      +'<div class="ch-sec-chart" id="chSecChart"></div>'
      +'<div class="ch-cumulative" id="chCumulative"></div>'
      +'<div class="modal-actions"><button class="m-btn-cancel" id="chClose">关闭</button></div>'
      +'</div>'
    var sheet=modal.querySelector('.modal-sheet')
    if(sheet){
      sheet.innerHTML=h2
      // 每秒点击次数柱状图
      var chartEl=document.getElementById('chSecChart')
      if(chartEl)renderPerSecChart(chartEl,state.perSecHits,state.duration)
      var cumEl=document.getElementById('chCumulative')
      if(cumEl){
        var cum=c.seasonBonus
        cumEl.innerHTML='<div style="font-size:var(--fs-2xs);color:var(--text3);margin-top:8px">本月累计: ⚔️+'+cum.atk+' 🛡️+'+cum.def+' ❤️+'+cum.hp+'</div>'
      }
      var closeBtn=document.getElementById('chClose')
      if(closeBtn)closeBtn.addEventListener('click',function(){modal.remove();renderSummonPanel();renderGame()})
      // 结算后可点背景关闭（游戏中 noBackdrop）
      modal.addEventListener('click',function(e){if(e.target===e.currentTarget)modal.remove()})
    }
  }

  /* 每秒点击次数柱状图（纯 div，移动端友好） */
  function renderPerSecChart(container,perSec,duration){
    var n=perSec&&perSec.length?perSec.length:duration
    var maxHits=1
    for(var i=0;i<n;i++){if((perSec[i]||0)>maxHits)maxHits=perSec[i]}
    var h='<div style="font-size:var(--fs-2xs);color:var(--text3);margin:8px 0 4px">⏱️ 每秒点击次数</div><div style="display:flex;align-items:flex-end;gap:3px;height:64px;padding:0 2px">'
    for(var i=0;i<n;i++){
      var v=perSec[i]||0
      var bh=Math.max(2,Math.round(v/maxHits*56))
      var c=v>=maxHits&&maxHits>1?'var(--orange)':'var(--blue)'
      h+='<div style="flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:2px" title="第'+(i+1)+'秒: '+v+'次"><div style="height:'+bh+'px;background:'+c+';border-radius:3px 3px 0 0;width:100%;min-width:4px"></div><span style="font-size:var(--fs-3xs);color:var(--text3)">'+(i+1)+'</span></div>'
    }
    h+='</div>'
    container.innerHTML=h
  }
  
  // Start countdown
  state.ticking=true
  state.timer=setInterval(function(){
    state.timeLeft--
    if(timerEl)timerEl.textContent=state.timeLeft+'s'
    if(timerBar)timerBar.style.width=(state.timeLeft/state.duration*100)+'%'
    if(timerBar&&state.timeLeft<=3)timerBar.classList.add('urgent')
    if(state.timeLeft<=0){
      endChallenge()
    }
  },1000)
  
  // Overlay click: no close during game (prevent accidental exit)
  modal.addEventListener('click',function(e){
    if(e.target===e.currentTarget&&state.ticking===false)modal.remove()
  })
}

/* ========== CHALLENGE HISTORY ========== */
function showChallengeHistory(){
  var c=getChallenge()
  var h=c.history||[]
  var modal=openModal(null,'chHistoryModal')
  var html='<div class="modal-sheet"><div class="modal-handle"></div><div class="modal-title">📜 历史召唤成绩</div>'
  if(!h.length){
    html+='<div class="empty"><span class="empty-e">📜</span><div class="empty-t">暂无挑战记录</div><div class="empty-s">完成隐藏挑战后自动记录</div></div>'
  }else{
    var rows=h.slice().reverse().map(function(r,i){
      var buffLabel=r.buff?hotBuffLabel(r.buff):'无 buff'
      return'<div class="ec" style="margin-bottom:6px"><div class="ec-hdr"><div class="ec-ex">'+r.date+'</div><div class="ec-actions"><span style="font-size:var(--fs-3xs);color:var(--text3)">#'+(h.length-i)+'</span></div></div>'
        +'<div style="font-size:var(--fs-2xs);color:var(--text2);line-height:1.7;padding:2px 0">'
        +'⚔️ '+r.dmg+' 伤害 · 🎯 '+r.hits+' 次 ('+r.avgRate+'/秒) · 💥 '+r.crits+' 暴击<br>'
        +'🥇 最强 '+r.maxHit+' · 🎁 ⚔️+'+r.atk+' 🛡️+'+r.def+' ❤️+'+r.hp
        +(r.buff?'<br><span style="color:#fbbf24">'+buffLabel+'</span>':'')
        +'</div></div>'
    }).join('')
    html+='<div style="max-height:55vh;overflow-y:auto">'+rows+'</div>'
  }
  html+='<div class="modal-actions"><button class="m-btn-cancel" id="chHistClose">关闭</button></div></div>'
  modal.innerHTML=html
  document.getElementById('chHistClose').addEventListener('click',function(){modal.remove()})
  modal.addEventListener('click',function(e){if(e.target===e.currentTarget)modal.remove()})
}

/* ========== v2.2 WP-H4：挑战页「每月最高记录」 ==========
   文档原文（doc/2.2 修改-补充.md）只有一句：
     「挑战页面 - 增加每个月最高记录查看」
   → 未给字段口径，本实现在此定义并写进测试锁定：
     每月一条记录：count 通关次数 / totalDmg 累计伤害 / bestDmg 单次最高伤害（bestDate）
                   atk·def·hp 属性奖励合计 / bestAtk·bestDef·bestHp 单次最高奖励那一场的奖励
                   firstDate·lastDate 首末日期
   归档与重置：按**月键（YYYY-MM）分桶** —— 跨月自动开新桶（新月从 0 开始），旧月桶原样保留即「归档」；
   本月键记在 `c.monthlyKey`（写法与 pet-store.js 的 monthlyKey 同款），
   同月重复调用**幂等**（不会重复计入，也不会把旧月数据清掉）。 */

/* 归档保留的月份数上限（防存档无限膨胀） */
var CHALLENGE_MONTH_KEEP = 24;

/* 取「所属自然月」键：传日期串 'YYYY-MM-DD'、Date 对象，或不传（=今天） */
function chMonthOf(when){
  if(when==null)return today().slice(0,7)
  if(when instanceof Date){
    if(typeof monthKey==='function')return monthKey(when)
    return when.getFullYear()+'-'+String(when.getMonth()+1).padStart(2,'0')
  }
  return String(when).slice(0,7)
}

function blankChallengeMonth(mk){
  return { month:mk, count:0, totalDmg:0, bestDmg:0, bestDate:'',
           atk:0, def:0, hp:0, bestAtk:0, bestDef:0, bestHp:0,
           firstDate:'', lastDate:'' }
}

/* 把一条成绩并入某月桶（内部共用；不碰 c.monthlyKey） */
function mergeChallengeMonth(m, rec){
  rec=rec||{}
  m.count=(m.count||0)+1
  m.totalDmg=(m.totalDmg||0)+(rec.dmg||0)
  m.atk=(m.atk||0)+(rec.atk||0)
  m.def=(m.def||0)+(rec.def||0)
  m.hp=(m.hp||0)+(rec.hp||0)
  if((rec.dmg||0)>(m.bestDmg||0)){
    m.bestDmg=rec.dmg||0; m.bestDate=rec.date||''
    m.bestAtk=rec.atk||0; m.bestDef=rec.def||0; m.bestHp=rec.hp||0
  }
  if(!m.firstDate||(rec.date&&rec.date<m.firstDate))m.firstDate=rec.date||''
  if(!m.lastDate||(rec.date&&rec.date>m.lastDate))m.lastDate=rec.date||''
  return m
}

/* 一次性迁移回填：旧存档没有 c.monthlyKey 时，用现存 history 兜底建桶（幂等：有键即跳过）。
   ⚠️ 调用点必须在「push 新成绩之前」，否则新成绩会被回填与合并各计一次。 */
function ensureChallengeMonthly(c){
  c=c||getChallenge()
  if(c.monthlyKey)return c
  c.monthly=(c.monthly&&typeof c.monthly==='object'&&!Array.isArray(c.monthly))?c.monthly:{}
  ;(c.history||[]).forEach(function(r){
    if(!r||!r.date)return
    var mk=chMonthOf(r.date)
    var m=c.monthly[mk]
    if(!m||typeof m!=='object'){m=blankChallengeMonth(mk);c.monthly[mk]=m}
    mergeChallengeMonth(m,r)
  })
  c.monthlyKey=chMonthOf()
  return c
}

/* 归档上限：只保留最近 CHALLENGE_MONTH_KEEP 个月（从最旧开始删；keep 指定的月永不删） */
function trimChallengeMonthly(c, keep){
  var keys=Object.keys(c.monthly||{}).sort()
  while(keys.length>CHALLENGE_MONTH_KEEP){
    var oldest=keys.shift()
    if(oldest!==keep)delete c.monthly[oldest]
  }
}

/* 一次挑战结算后并入所属月份桶（endChallenge 调用；返回该月桶） */
function recordChallengeMonth(c, rec){
  c=c||getChallenge()
  ensureChallengeMonthly(c)
  var mk=chMonthOf(rec&&rec.date)
  c.monthly=(c.monthly&&typeof c.monthly==='object'&&!Array.isArray(c.monthly))?c.monthly:{}
  var m=c.monthly[mk]
  if(!m||typeof m!=='object'){m=blankChallengeMonth(mk);c.monthly[mk]=m}
  mergeChallengeMonth(m,rec)
  trimChallengeMonthly(c, mk)
  c.monthlyKey=chMonthOf()
  return m
}

/* 跨月归档/重置：把「本月键」推进到 now 所指自然月（不传 = 今天）。
   - 旧月桶原样保留 = 归档；新月尚无桶 → 首次记录时自动开桶（显示端视为「本月 0 次」）
   - 幂等：同月重复调用只把键写回同值，不重复计入任何数据 */
function challengeMonthlyRollover(now){
  var c=getChallenge()
  ensureChallengeMonthly(c)
  var cur=chMonthOf(now)
  var prev=c.monthlyKey||''
  var rolled=!!prev&&prev!==cur
  trimChallengeMonthly(c, cur)
  c.monthlyKey=cur
  saveChallenge(c)
  return { rolled:rolled, monthKey:cur, prevMonthKey:prev }
}

/* 月份记录列表（新→旧），供挑战页「每月记录」渲染 */
function listChallengeMonthly(c){
  c=c||getChallenge()
  ensureChallengeMonthly(c)
  var out=[]
  Object.keys(c.monthly||{}).forEach(function(k){
    var m=c.monthly[k]
    if(m&&typeof m==='object')out.push(m)
  })
  out.sort(function(a,b){return String(b.month||'').localeCompare(String(a.month||''))})
  return out
}

/* 本月记录（无则返回空骨架，便于 UI 直接显示 0） */
function currentChallengeMonth(c){
  c=c||getChallenge()
  ensureChallengeMonthly(c)
  var mk=chMonthOf()
  var m=(c.monthly||{})[mk]
  return (m&&typeof m==='object')?m:blankChallengeMonth(mk)
}

/* ========== INTEGRATION ========== */
// Called from checkMonthlyReset to clear season bonus
function resetChallengeSeason(){
  /* v2.2 WP-H4：跨月归档 —— 旧月桶保留（=归档），本月键推进到新自然月（幂等）。
     先跑归档再读一次存档，避免覆盖下面写回的本月奖励清零。 */
  challengeMonthlyRollover()
  var c=getChallenge()
  c.seasonBonus={atk:0,def:0,hp:0}
  c.lastSeasonMonth=today().slice(0,7)
  saveChallenge(c)
  /* v2.2 WP-H9：月度重置（**未用技能点清零** + **已学技能等级减半**，不返还点数）。
     ⚠️ app.js 的 checkMonthlyReset() 是本项目唯一的月度触发点，而它调用本函数；
     本批次白名单不含 app.js，故重置在此接线。monthlyResetSkillState() 自带月度键幂等，
     即便被重复调用，同一自然月内也只扣减一次。 */
  if(typeof monthlyResetSkillState==='function'){
    try{
      var _sk=monthlyResetSkillState()
      if(_sk&&_sk.ok)toast('📅 月度重置：未用技能点已清零，技能等级减半','s')
    }catch(e){console.warn('[challenge] 技能月度重置失败',e)}
  }
  toast('🔬 隐藏挑战奖励已重置','s')
}

// Called from getGameStats to add challenge bonus to attributes
function getChallengeBonus(){
  var c=getChallenge()
  return c.seasonBonus||{atk:0,def:0,hp:0}
}

