/* ===== linechart.js ===== */
/* ============================================
   MyHealth — LineChart (reusable Canvas renderer)
   v3: 主题取色 + resize 重绘 + 监听器去重
   P0-8：原来硬编码 rgba(255,255,255,.04) 的网格在浅色主题下完全不可见，
         且 canvas.style.width 写死 px 与 CSS width:100% 冲突、无 resize 监听。
   ============================================ */

/* 支持 #rgb / #rrggbb / rgb() / rgba() 输入；非可解析值原样返回（带 alpha 时忽略） */
function hexToRgba(hex,alpha){
  if(!hex)return 'rgba(0,0,0,'+alpha+')';
  var s=String(hex).trim();
  if(s.charAt(0)==='#'){
    var h=s.slice(1);
    if(h.length===3)h=h.charAt(0)+h.charAt(0)+h.charAt(1)+h.charAt(1)+h.charAt(2)+h.charAt(2);
    if(h.length!==6)return s;
    var r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);
    if(isNaN(r)||isNaN(g)||isNaN(b))return s;
    return 'rgba('+r+','+g+','+b+','+alpha+')';
  }
  var m=s.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
  if(m)return 'rgba('+m[1]+','+m[2]+','+m[3]+','+alpha+')';
  return s;
}

/* 允许调用方传 'var(--brand-fill)' 这类令牌，这里解析成真实色值 */
function lcVar(s,fallback){
  if(!s)return fallback;
  if(String(s).indexOf('var(')<0)return s;
  var name=String(s).slice(String(s).indexOf('var(')+4);
  name=name.slice(0,name.indexOf(')')).trim();
  var cs=window.getComputedStyle?window.getComputedStyle(document.documentElement):null;
  var out=cs?(cs.getPropertyValue(name)||''):'';
  return out.trim()?out.trim():fallback;
}

/* canvas 2D 上下文不解析 CSS 变量（fillStyle='var(--bg2)' 会被静默忽略），
   必须手动取计算后的真实色值。 */
function lcTheme(){
  var cs=window.getComputedStyle?window.getComputedStyle(document.documentElement):null;
  function v(name,fallback){
    if(!cs)return fallback;
    var s=cs.getPropertyValue(name);
    return (s&&s.trim())?s.trim():fallback;
  }
  return {
    grid:   v('--bd','#1e293b'),
    axis:   v('--text3','#94a3b8'),
    text:   v('--text','#f1f5f9'),
    surface:v('--surface','#111827'),
    brand:  v('--brand-fill','#F97316')
  };
}

/* 已注册的图表实例，用于窗口尺寸变化时统一重绘 */
var _lcCharts=[];
var _lcTimer=null;
function lcRedrawAll(){
  clearTimeout(_lcTimer);
  _lcTimer=setTimeout(function(){
    for(var i=0;i<_lcCharts.length;i++){
      var c=_lcCharts[i];
      if(!c.isConnected){_lcCharts.splice(i--,1);continue}
      if(c._lcOpts)drawLineChart(c,c._lcOpts);
    }
  },150);
}
if(typeof window!=='undefined'&&window.addEventListener){
  window.addEventListener('resize',lcRedrawAll);
  window.addEventListener('orientationchange',lcRedrawAll);
}

/* v2.2 WP-H3：图表数值的**展示层**格式化 —— 去掉浮点尾数（如 2862.1000000000004 → 2862.1）。
   只作用于「最新值标签 / 点击浮层」的文本，坐标与曲线仍用原值计算（不改数值本身）。 */
function lcFmt(v){
  if(typeof v!=='number'||!isFinite(v))return v;
  var r=Math.round(v*100)/100;
  return Math.abs(r-Math.round(r))<1e-9?String(Math.round(r)):String(parseFloat(r.toFixed(2)));
}

function drawLineChart(canvas,opts){
  if(!canvas)return;
  canvas._lcOpts=opts;

  var labels=opts.labels||[],values=opts.values||[],suffix=opts.suffix||'';
  var T=lcTheme();
  var color=lcVar(opts.color,T.brand);
  var dpr=Math.min(window.devicePixelRatio||1,2);

  // 尺寸取自 CSS 布局后的真实盒子（原来写死 canvas.style.width 会盖掉 width:100%，
  // 且旋转屏幕后永不重绘）。宽度完全交给 CSS，这里只设像素缓冲区。
  var rect=canvas.getBoundingClientRect();
  var W=Math.round(rect.width||0),H=Math.round(rect.height||0);
  if(W<1)W=Math.min(540,canvas.parentElement?(canvas.parentElement.clientWidth||280):280);
  if(H<1)H=180;

  canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);
  var ctx=canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,W,H);

  var pad=44;

  if(values.length<2){
    ctx.fillStyle=T.axis;ctx.font='12px sans-serif';ctx.textAlign='center';
    ctx.fillText(opts.emptyMsg||'至少需要 2 条记录才能显示趋势',W/2,H/2);
    return;
  }

  var min=Math.floor(Math.min.apply(null,values)-1),max=Math.ceil(Math.max.apply(null,values)+1);
  if(min===max){min--;max++}
  var range=Math.max(1,max-min),n=values.length;
  var xs=values.map(function(_,i){return pad+i*(W-pad*2)/(n-1)});
  var yv=function(v){return H-24-(v-min)/range*(H-44)};

  // Subtle grid（跟随主题，浅色下同样可见）
  ctx.strokeStyle=hexToRgba(T.grid,.6);ctx.lineWidth=.5;
  for(var v=min;v<=max;v++){if(v===min||v===max)continue;var y=yv(v);ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);ctx.stroke()}

  // Base line
  ctx.strokeStyle=hexToRgba(T.grid,.9);ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(pad,yv(min));ctx.lineTo(W-pad,yv(min));ctx.stroke()

  // X-axis labels（12px 起步，移动端可读）
  ctx.fillStyle=T.axis;ctx.font='12px sans-serif';ctx.textAlign='center';
  var step=Math.max(1,Math.floor(n/6));
  for(var i=0;i<n;i+=step){ctx.fillText(labels[i]||'',xs[i],H-6)}
  if(n>1){ctx.fillText(labels[0]||'',xs[0],H-6);ctx.fillText(labels[n-1]||'',xs[n-1],H-6)}

  // Y-axis labels
  ctx.textAlign='right';ctx.font='12px sans-serif';
  ctx.fillText(min,W-4,yv(min)+4);ctx.fillText(max,W-4,yv(max)+4);

  // Gradient area fill
  var grd=ctx.createLinearGradient(0,yv(max),0,yv(min));
  grd.addColorStop(0,hexToRgba(color,0));grd.addColorStop(1,hexToRgba(color,.12));
  ctx.beginPath();ctx.moveTo(xs[0],yv(min));
  for(var i=0;i<n-1;i++){
    var xc=(xs[i]+xs[i+1])/2,y0=yv(values[i]),y1=yv(values[i+1]);
    ctx.bezierCurveTo(xc,y0,xc,y1,xs[i+1],y1);
  }
  ctx.lineTo(xs[n-1],yv(min));ctx.lineTo(xs[0],yv(min));ctx.closePath();
  ctx.fillStyle=grd;ctx.fill();

  // Smooth line
  ctx.beginPath();ctx.moveTo(xs[0],yv(values[0]));
  for(var i=0;i<n-1;i++){
    var xc=(xs[i]+xs[i+1])/2,y0=yv(values[i]),y1=yv(values[i+1]);
    ctx.bezierCurveTo(xc,y0,xc,y1,xs[i+1],y1);
  }
  ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();

  // Dots —— 空心效果靠底色挖孔，必须用真实色值（原来写 var(--bg2) 是静默失效的）
  for(var i=0;i<n;i++){
    var xx=xs[i],yy=yv(values[i]);
    ctx.beginPath();ctx.arc(xx,yy,4,0,Math.PI*2);ctx.fillStyle=T.surface;ctx.fill();
    ctx.beginPath();ctx.arc(xx,yy,3.5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();
  }

  // Latest value label
  var last=values[n-1];
  ctx.fillStyle=color;ctx.font='bold 12px sans-serif';ctx.textAlign='center';
  ctx.fillText(lcFmt(last)+suffix,xs[n-1],yv(last)-12);

  /* ========== TOOLTIP (tap/touch/click) ========== */
  // 复用同一个 tip 节点、监听器只绑一次（原来每次绘制都新建 + 重复绑定，会堆积孤儿节点）
  var tip=canvas._lcTip;
  if(!tip){
    tip=document.createElement('div');
    tip.setAttribute('role','status');
    tip.style='position:absolute;pointer-events:none;background:var(--surface);border:var(--bw) solid var(--bd-l);border-radius:8px;padding:4px 10px;font-size:var(--fs-xs);color:var(--text);font-weight:600;white-space:nowrap;z-index:var(--z-content);box-shadow:var(--sh-2);display:none;transform:translate(-50%,-120%)';
    canvas._lcTip=tip;
  }
  if(tip.parentNode!==canvas.parentElement&&canvas.parentElement)canvas.parentElement.appendChild(tip);
  if(canvas.parentElement){
    var ppos=canvas.parentElement.style.position;
    if(ppos!=='absolute'&&ppos!=='relative')canvas.parentElement.style.position='relative';
  }

  function showTip(idx){
    if(idx<0||idx>=n)return;
    tip.textContent=labels[idx]+' · '+lcFmt(values[idx])+suffix;
    tip.style.left=xs[idx]+'px';tip.style.top=yv(values[idx])+'px';
    tip.style.display='block';
    drawDot(idx);
  }
  function hideTip(){tip.style.display='none'}
  function drawDot(idx){
    var c=document.createElement('canvas');
    c.style='position:absolute;left:0;top:0;pointer-events:none;z-index:var(--z-content)';
    c.width=canvas.width;c.height=canvas.height;
    var c2=c.getContext('2d');c2.setTransform(dpr,0,0,dpr,0,0);
    c2.beginPath();c2.arc(xs[idx],yv(values[idx]),6,0,Math.PI*2);
    c2.fillStyle=hexToRgba(color,.25);c2.fill();
    c2.beginPath();c2.arc(xs[idx],yv(values[idx]),4,0,Math.PI*2);
    c2.fillStyle=color;c2.fill();
    if(canvas.parentElement)canvas.parentElement.appendChild(c);
    setTimeout(function(){if(c.parentNode)c.remove()},50);
  }
  function hitTest(px,py){
    var best=-1,bd=1e9;
    for(var i=0;i<n;i++){
      var dx=px-xs[i],dy=py-yv(values[i]);
      var d=Math.sqrt(dx*dx+dy*dy);
      if(d<bd){bd=d;best=i}
    }
    return bd<30?best:-1;
  }

  if(!canvas._lcBound){
    canvas._lcBound=true;
    _lcCharts.push(canvas);
    canvas.addEventListener('click',function(e){
      var r=canvas.getBoundingClientRect();
      var idx=hitTest(e.clientX-r.left,e.clientY-r.top);
      if(idx>=0)showTip(idx);
    });
    canvas.addEventListener('touchstart',function(e){
      var t=e.touches[0],r=canvas.getBoundingClientRect();
      var idx=hitTest(t.clientX-r.left,t.clientY-r.top);
      if(idx>=0){showTip(idx);e.preventDefault()}
    },{passive:false});
    canvas.addEventListener('touchend',function(){setTimeout(hideTip,1800)});
  }
}

;
/* ===== app.js ===== */
/* ============================================
   MyHealth — App Core (Data Layer + Events + Init)
   ============================================ */

/* ========== DATA LAYER (via store.js) ========== */
function getStr(d){var s=store.get('strength')||{entries:[]};return(s.entries||[]).filter(function(e){return e.date===d}).sort(function(a,b){return(a.createdAt||0)-(b.createdAt||0)})}
function addStr(e){var s=store.get('strength')||{entries:[]};e.id=uid();e.createdAt=Date.now();s.entries.push(e);store.set('strength',s);checkPR(e)}
function updateStr(id,data){var s=store.get('strength')||{entries:[]};var i=s.entries.findIndex(function(e){return e.id===id});if(i>-1){s.entries[i]=Object.assign({},s.entries[i],data);store.set('strength',s)}}
function delStr(id){var s=store.get('strength')||{entries:[]};s.entries=s.entries.filter(function(e){return e.id!==id});store.set('strength',s)}
function checkPR(e){
  var prs=store.get('prs')||{}
  var ex=prs[e.exercise]||{}
  var broken=[]
  var w=e.eqWeight!=null?e.eqWeight:e.weight;
  var n=e.actualReps||(e.duration?e.duration:0);
  var vol=w*n
  if(!ex.maxWeight||w>ex.maxWeight){ex.maxWeight=w;ex.weightDate=e.date;broken.push('重量 '+w+'kg')}
  if(!ex.maxReps||n>ex.maxReps){ex.maxReps=n;ex.repsDate=e.date;broken.push('次数 '+n+'次')}
  if(!ex.maxVolume||vol>ex.maxVolume){ex.maxVolume=vol;ex.volDate=e.date;broken.push('容量 '+Math.round(vol)+'kg')}
  if(broken.length){prs[e.exercise]=ex;store.set('prs',prs);toast('🏆 '+e.exercise+' 新PR: '+broken.join(', '),'s')}
}

function getPlans(){var p=store.get('plans');return p?p.plans||[]:[]}
function savePlans(plans){store.set('plans',{plans:plans})}
function getMissed(){var m=store.get('missed');return m?m.notes||{}:{}}
function saveMissed(notes){store.set('missed',{notes:notes})}
function getCardioPlans(){var p=store.get('cardioPlans');return p?p.plans||[]:[]}
function saveCardioPlans(plans){store.set('cardioPlans',{plans:plans})}

function getCar(d){var c=store.get('cardio')||{entries:[]};return(c.entries||[]).filter(function(e){return e.date===d}).sort(function(a,b){return(a.createdAt||0)-(b.createdAt||0)})}
function addCar(e){var c=store.get('cardio')||{entries:[]};e.id=uid();e.createdAt=Date.now();c.entries.push(e);store.set('cardio',c)}
function delCar(id){var c=store.get('cardio')||{entries:[]};c.entries=c.entries.filter(function(e){return e.id!==id});store.set('cardio',c)}

function getWt(){var w=store.get('weight')||{records:[]};return(w.records||[]).sort(function(a,b){return a.date<b.date?1:-1})}
function addWt(r){var w=store.get('weight')||{records:[]};r.id=uid();r.createdAt=Date.now();w.records.push(r);store.set('weight',w)}

function getProf(){return store.get('profile')||{height:175,gender:'男',birthYear:1990}}
function setProf(p){store.set('profile',p)}

function getGame(){return store.get('game')||{cleared:[],current:''}}
function setGame(g){store.set('game',g)}
function getRefine(){return store.get('refine')||{points:0,totalEarned:0,unlocked:false,upgrades:{}}}
function saveRefine(r){store.set('refine',r||{})}

/* ========== EXERCISE LIBRARY ========== */
function getExercises(){return store.get('exercises')||[]}
function saveExercises(list){store.set('exercises',list||[])}
function getExerciseMap(){
  var map={};
  getExercises().forEach(function(ex){map[ex.id]=ex});
  return map;
}
function getStrengthExercises(){return getExercises().filter(function(ex){return ex.type==='strength'})}
function getCardioExercises(){return getExercises().filter(function(ex){return ex.type==='cardio'})}

/* 动作改名 / 合并（v2.0.6）
   把 oldId 动作改名为 newName：
   - newName 已存在 → 合并：删除旧条目，历史训练/计划引用归并到新名，
     PR 按最大值合并（重量/次数/容量分别取 max，日期取较大者那条），
     目标动作无 dsId 时继承源的
   - newName 不存在 → 纯改名（id=name 同步更新，dsId/ratio 等字段保留）
   四库联动：exercises / strength.entries / prs 键 / plans 引用 */
function renameOrMergeExercise(oldId,newName){
  if(!oldId||!newName||oldId===newName)return{ok:false}
  var list=getExercises()
  var src=list.find(function(x){return x.id===oldId})
  if(!src)return{ok:false}
  var dstRef=list.find(function(x){return x.id===newName})
  var merged=!!dstRef
  if(merged){
    if(!dstRef.dsId&&src.dsId)dstRef.dsId=src.dsId   // 目标无关联则继承
    list=list.filter(function(x){return x.id!==oldId})
  }else{
    src.id=newName;src.name=newName
  }
  saveExercises(list)
  // 历史训练记录
  var st=store.get('strength')||{entries:[]}
  var stChanged=false
  ;(st.entries||[]).forEach(function(e){if(e.exercise===oldId){e.exercise=newName;stChanged=true}})
  if(stChanged)store.set('strength',st)
  // PR：键迁移 / 最大值合并
  var prs=store.get('prs')||{}
  var srcPr=prs[oldId]
  if(srcPr){
    if(merged&&prs[newName]){
      var np=prs[newName]
      ;[['maxWeight','weightDate'],['maxReps','repsDate'],['maxVolume','volDate']].forEach(function(pair){
        var k=pair[0],dk=pair[1]
        if(srcPr[k]&&(np[k]==null||srcPr[k]>np[k])){np[k]=srcPr[k];np[dk]=srcPr[dk]}
      })
    }else{
      prs[newName]=srcPr
    }
    delete prs[oldId]
    store.set('prs',prs)
  }
  // 训练计划引用
  var pl=store.get('plans')||{plans:[]}
  var plChanged=false
  ;(pl.plans||[]).forEach(function(p){(p.exercises||[]).forEach(function(e){if(e.exercise===oldId){e.exercise=newName;plChanged=true}})})
  if(plChanged)store.set('plans',pl)
  return{ok:true,merged:merged,dstDsId:merged?(dstRef&&dstRef.dsId)||null:null}
}

/* ========== INIT ========== */
function init(){
  document.getElementById('appVersion').textContent='v'+APP_VERSION
  document.documentElement.classList.add('no-transition')
  setTheme(getTheme())
  requestAnimationFrame(()=>document.documentElement.classList.remove('no-transition'))

  buildWtGrid(document.getElementById('strWeight'),_strSelW,w=>_strSelW=w)

  var sug=document.getElementById('strSuggest')
  if(sug){
    sug.innerHTML='';
    var strEntries=((store.get('strength')||{entries:[]}).entries)||[];
    var freq={};
    strEntries.forEach(function(e){if(e.exercise)freq[e.exercise]=(freq[e.exercise]||0)+1});
    var sorted=getStrengthExercises().slice().sort(function(a,b){
      return(freq[b.name]||0)-(freq[a.name]||0)
    });
    sorted.forEach(function(n){
      var b=document.createElement('button');b.textContent=n.name;
      b.addEventListener('click',function(){document.getElementById('strExercise').value=n.name;adaptStrForm(n.name)});sug.appendChild(b);
    });
  }
  var dl=document.getElementById('strExList')
  if(dl){
    dl.innerHTML='';
    getStrengthExercises().forEach(function(n){var o=document.createElement('option');o.value=n.name;dl.appendChild(o)});
  }
  var strInput=document.getElementById('strExercise');
  if(strInput){strInput.addEventListener('change',function(){adaptStrForm(strInput.value.trim())});strInput.addEventListener('input',function(){adaptStrForm(strInput.value.trim())})}

  var ct=document.getElementById('carTypes')
  initCardioTypes()

  migrateExercises()
  migrateExercisesV17()
  migrateOldData()
  checkMonthlyReset()
  backfillJunePermBonus()
  fixDefBonusRatio()

  autoLinkExercises()
  renderStr();renderCar();renderProf();renderGame();renderSettings();renderSummonPanel()
  /* v2.14.36：动作数据集 1161KB（占源码 44%）不再进首屏包 —— 空闲时补拉，
     拉到后把依赖它的卡片（动作库 / 训练动作图）刷一遍。 */
  setTimeout(prefetchDataset,1200)
}

function refreshAfterDataset(){
  try{
    if(typeof renderExLibrary==='function')renderExLibrary()
    if(typeof renderStr==='function')renderStr()
    if(typeof initCardioTypes==='function')initCardioTypes()
  }catch(e){console.warn('[app] 数据集到达后刷新失败（已忽略）',e)}
}

function prefetchDataset(){
  try{ if(typeof EXD==='undefined'||EXD.ready())return; EXD.load(function(ok){ if(ok)refreshAfterDataset() }) }
  catch(e){console.warn('[app] 动作百科空闲预取失败（已忽略）',e)}
}

/* 自动关联动作百科：给未关联动作按中文名匹配 dsId（持久化）
   v2.14.36：数据集可能尚未加载 → 先触发加载再回填（不阻塞首屏渲染） */
function autoLinkExercises(){
  try{
    if(typeof EXD==='undefined')return;
    if(!EXD.ready()){EXD.load(function(ok){ if(ok)autoLinkExercises() });return}
    var list=store.get('exercises')||[];
    var changed=false;
    list.forEach(function(ex){
      if(!ex.dsId){
        var cands=EXD.matchCandidates(ex.name,1);
        if(cands&&cands.length){ex.dsId=cands[0].item.id;changed=true;}
      }
    });
    if(changed)store.set('exercises',list);
  }catch(e){console.warn('[app] 回填 dsId 失败（已忽略）',e)}
}

/* ========== EVENT DELEGATION ========== */
/* Tab event handlers register here — each returns true if handled.
   Dispatch is wrapped in try/catch so one module's bug never
   blocks the others (or the default handler).
   NOTE: resolved lazily — tab-*.js load after app.js, so direct
   references at load time would be undefined. */
function getTabHandlers(){return[onStrengthEvent,onCardioEvent,onProfileEvent,onGameEvent,onSettingsEvent]}

document.addEventListener('click',function(e){
  const el=e.target.closest('button,[id],[data-a],[data-s],[data-date]')
  if(!el)return
  const id=el.id,act=el.dataset.a,st=el.dataset.s

  if(el.classList.contains('tab-btn')){
    if(el.dataset.tab)switchTab(el.dataset.tab)
    else if(el.dataset.sub)switchSub(el.closest('.tab-content').id.replace('tab','').toLowerCase(),el.dataset.sub)
    return
  }
  if(id==='themeToggle'){toggleTheme();return}
  if(id==='syncBtn'){showSyncDialog();return}

  if(el.classList.contains('speed-btn')&&el.dataset.speed){
    document.querySelectorAll('.speed-btn').forEach(b=>b.classList.remove('active'))
    el.classList.add('active');_battleSpeed=parseInt(el.dataset.speed);return
  }
  // v2.1.6：命中模态遮罩必须走**真正的关闭**（移除元素 + 解锁滚动）。
  // 旧实现只 classList.remove('open') → 遮罩变 display:none 但 body 仍是 position:fixed，
  // 页面从此永久无法滚动。现在由 openModal 托管的模态调 _close()；
  // data-no-auto-close 的（如隐藏挑战小游戏进行中）跳过，交给调用方自己管。
  if(el.classList.contains('modal-overlay')&&el.dataset.modalManaged){
    if(!el.dataset.noAutoClose){
      if(typeof el._close==='function')el._close()
      else if(el.parentNode)el.remove()
    }
    return
  }

  if(st&&el.classList.contains('sp-btn')){
    const dir=el.dataset.d;const isTgt=st==='strTgt'
    const vid=isTgt?'strTgtVal':'strActVal'
    const v=document.getElementById(vid);let n=parseInt(v.textContent,10)
    n=dir==='+'?Math.min(n+1,999):Math.max(n-1,0);v.textContent=n;return
  }

  const handlers=getTabHandlers()
  for(let i=0;i<handlers.length;i++){
    try{
      if(handlers[i](el,id,act))return
    }catch(err){
      console.error('[handler]',err)
    }
  }
})

/* ========== TAB SWITCHING ========== */
var _activeTab='training';
function switchTab(name){
  _activeTab=name;
  /* v2.14.14（敌群自动战斗的停止条件③）：切走「挑战」tab → 立即停自动 + 清定时器。
     敌群 overlay 挂在 #tabGame 内部，切走后没人看得见；继续推进等于偷偷把一局打完。
     `stopGroupAuto` 由 game-render.js 提供（typeof 守卫，页面加载顺序/桩环境都不会炸）。 */
  if(name!=='game'&&typeof stopGroupAuto==='function')stopGroupAuto('切换 tab：'+name)
  document.querySelectorAll('.tab-bar > .tab-btn[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name))
  document.querySelectorAll('.tab-content').forEach(c=>c.classList.toggle('active',c.id==='tab'+name.charAt(0).toUpperCase()+name.slice(1)))
  if(name==='training'){renderStr();renderCar()}
  if(name==='profile')renderProf()
  if(name==='game')renderGame()
  if(name==='settings')renderSettings()
}

/* ========== GENERIC SUB-TAB SWITCHING ========== */
function switchSub(tabName,sub){
  tabName=tabName.toLowerCase();
  var container=document.getElementById('tab'+tabName.charAt(0).toUpperCase()+tabName.slice(1));
  if(!container)return;
  container.querySelectorAll('.sub-tab-bar .tab-btn[data-sub]').forEach(function(b){b.classList.toggle('active',b.dataset.sub===sub)});
  container.querySelectorAll('.sub-tab').forEach(function(c){c.classList.toggle('active',c.id==='sub'+sub.charAt(0).toUpperCase()+sub.slice(1))});
  if(tabName==='profile'&&sub==='training'){renderStats();renderHeatmap()}
  if(tabName==='settings'){
    if(sub==='library')renderExLibrary();
    if(sub==='plans')renderSettingsPlans();
    if(sub==='game')renderSettingsGame();
    if(sub==='data')renderSettingsData();
  }
  if(tabName==='training'){
    if(sub==='strength')renderStr();
    if(sub==='cardio')renderCar();
  }
}

