/* ========== SUB-TAB: EXERCISE LIBRARY ========== */
function renderExLibrary(){
  var el=document.getElementById('subLibrary');if(!el)return
  var list=getExercises();
  var strength=list.filter(function(ex){return ex.type==='strength'});
  var cardio=list.filter(function(ex){return ex.type==='cardio'});

  var h='<h2 class="section-hdr">🏋️ 力量动作 <span style="font-size:var(--fs-3xs);color:var(--text3);font-weight:400">('+strength.length+')</span></h2>';
  if(strength.length){
    h+='<div class="ex-lib-list">';
    strength.forEach(function(ex){
      var ratioLabel=ex.ratio!=null?ex.ratio+'%':'100%';
      /* v2.14.26（评审 P2-9）：徽标 `🥇 100%` 会被读成「金牌/评分」，实际是折算率 → 改成「权重 100%」。 */
      h+=exCardHtml(ex,'权重 '+ratioLabel);
    });
    h+='</div>';
  }else{
    h+='<div class="empty"><span class="empty-e">🏋️</span><div class="empty-t">还没有力量动作</div></div>';
  }

  h+='<h2 class="section-hdr" style="margin-top:16px">🏃 有氧类型 <span style="font-size:var(--fs-3xs);color:var(--text3);font-weight:400">('+cardio.length+')</span></h2>';
  if(cardio.length){
    h+='<div class="ex-lib-list">';
    cardio.forEach(function(ex){
      var intLabel=INTENSITY_LEVELS.find(function(l){return l.id===ex.intensity})||{name:'中',emoji:'🟡'};
      var distLabel=ex.hasDist?'📏':'—';
      h+=exCardHtml(ex,intLabel.emoji+' '+distLabel,true);
    });
    h+='</div>';
  }else{
    h+='<div class="empty"><span class="empty-e">🏃</span><div class="empty-t">还没有有氧类型</div></div>';
  }

  h+='<button class="add-btn" id="exNewBtn" style="margin-top:12px">＋ 新建动作</button>';
  h+='<button class="add-btn" id="exWikiBtn" style="margin-top:8px;background:var(--bg);color:var(--text);border:var(--bw) solid var(--bd)">📖 动作百科'+(EXD.ready()?' ('+EXD.count()+')':'')+'</button>';
  h+='<div style="text-align:center;margin-top:6px;font-size:var(--fs-2xs);color:var(--text3)">力量 ratio 影响容量计算（100%=满容量）</div>';
  el.innerHTML=h;
  var wikiBtn=document.getElementById('exWikiBtn');
  if(wikiBtn)wikiBtn.addEventListener('click',function(){openDsPicker(null)});
  // Wire description toggle
  el.querySelectorAll('[data-a="exToggle"]').forEach(function(b){
    b.addEventListener('click',function(){
      var detail=this.parentNode.parentNode.querySelector('.ex-desc-full');
      if(detail){detail.style.display=detail.style.display==='none'?'block':'none'}
    });
  });
}

function exCardHtml(ex,badge,isCardio){
  var namePrefix=isCardio?(ex.emoji||'🏃')+' ':'';
  var linked=ex.dsId&&EXD.ready()?EXD.get(ex.dsId):null;
  /* v2.14.26（评审 P2-2）：图标按钮补可访问名称。原来读屏只会念「铅笔 / 垃圾桶」，26 个按钮全一样。 */
  var exName=String(ex.name==null?'':ex.name).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  var h='<div class="ec"><div class="ec-hdr"><div class="ec-ex">'+namePrefix+ex.name+(linked?' <span title="已关联动作百科" style="font-size:var(--fs-2xs)">📖</span>':'')+'<span class="ec-wt">'+badge+'</span></div><div class="ec-actions"><button class="ec-act" data-a="exEdit" data-id="'+ex.id+'" aria-label="编辑 '+exName+'">✏️</button><button class="ec-act" data-a="exDel" data-id="'+ex.id+'" aria-label="删除 '+exName+'">🗑️</button></div></div>';
  if(linked){
    var m=EXD.mediaUrls(linked.img);
    // 图片外侧大图 + 中文主/英文次
    h+='<div style="display:flex;gap:12px;margin-top:10px;align-items:center">'
      +'<img src="'+m.primary+'" loading="lazy" onerror="'+(m.fallback?"this.onerror=null;this.src='"+m.fallback+"'":"this.style.display='none'")+'" style="width:72px;height:72px;border-radius:12px;object-fit:cover;background:var(--bg2);border:var(--bw) solid var(--bd);flex-shrink:0">'
      +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:var(--fs-md);font-weight:700;color:var(--text1)">'+linked.zh+'</div>'
      +'<div style="font-size:var(--fs-2xs);color:var(--text3);margin-top:2px">'+linked.name+'</div>'
      +'<div style="margin-top:4px">'+tagHtml(linked.cat,'cat')+tagHtml(linked.eq,'eq')+'</div>'
      +'</div></div>';
  }
  if(ex.eqWeight){
    var unitLabel=ex.unit==='sec'?'秒':'次';
    h+='<div style="margin-top:6px;font-size:var(--fs-sm);color:var(--orange)">⚖️ 等效 '+ex.eqWeight+'kg/'+unitLabel+'（不计弯鿖重量）</div>';
  }
  if(ex.description){
    var first=mdFirstLine(ex.description);
    h+='<div style="margin-top:8px;font-size:var(--fs-sm);color:var(--text2);cursor:pointer" data-a="exToggle">'+first+'<span style="color:var(--text3);font-size:var(--fs-xs)"> …展开</span></div>';
    h+='<div class="ex-desc-full" style="display:none;margin-top:6px;padding:10px 12px;background:var(--bg);border-radius:var(--rs);border:var(--bw) solid var(--bd)">'+renderMd(ex.description)+'</div>';
  }
  h+='</div>';
  return h;
}

function showExEditor(editId){
  var list=getExercises();
  var ex=editId?list.find(function(x){return x.id===editId}):null;
  var isEdit=!!ex;
  if(!ex)ex={id:'',name:'',type:'strength',ratio:100,intensity:2,emoji:'🏃',hasDist:false,description:'',eqWeight:null,unit:'rep'};

  var modal=openModal(null,'exModal')
  var h='<div class="modal-sheet"><div class="modal-handle"></div><div class="modal-title">'+(isEdit?'✏️ 编辑动作':'＋ 新建动作')+'</div>';
  h+='<div class="fg"><span class="fl" id="lbl-s-g1">类型</span><div class="car-types" id="exTypeSel" role="group" aria-labelledby="lbl-s-g1">';
  h+='<button class="car-type'+(ex.type==='strength'?' selected':'')+'" data-extype="strength">💪 力量</button>';
  h+='<button class="car-type'+(ex.type==='cardio'?' selected':'')+'" data-extype="cardio">🏃 有氧</button>';
  h+='</div></div>';
  h+='<div class="fg"><label class="fl" for="exName">名称</label><input class="fi" id="exName" value="'+ex.name+'" placeholder="如: 弯举"></div>';
  h+='<div class="fg" id="exRatioFg"'+(ex.type==='strength'?'':' style="display:none"')+'><span class="fl" id="lbl-s-g2">力量比值 (ratio %) <span style="font-weight:400;text-transform:none">折算率10~100%</span></span><div class="stepper" style="max-width:160px" role="group" aria-labelledby="lbl-s-g2"><button class="sp-btn" id="exRatioD">−</button><span class="sp-val" id="exRatioVal">'+(ex.ratio!=null?ex.ratio:100)+'</span><button class="sp-btn" id="exRatioU">+</button></div></div>';
  h+='<div class="fg" id="exEqWeightFg"'+(ex.type==='strength'?'':' style="display:none"')+'><label class="fl" for="exEqWeight">等效重量 (kg/次) <span style="font-weight:400;text-transform:none">自重动作设此值，留空则用实际重量</span></label><input class="fi" id="exEqWeight" type="number" step="0.1" min="0" value="'+(ex.eqWeight!=null?ex.eqWeight:'')+'" placeholder="如: 0.5（留空=哑铃动作）"></div>';
  h+='<div class="fg" id="exUnitFg"'+(ex.type==='strength'?'':' style="display:none"')+'><span class="fl" id="lbl-s-g3">计量单位</span><div class="car-types" id="exUnitSel" role="group" aria-labelledby="lbl-s-g3">';
  h+='<button class="car-type'+(ex.unit!=='sec'?' selected':'')+'" data-exunit="rep">🔢 按次数</button>';
  h+='<button class="car-type'+(ex.unit==='sec'?' selected':'')+'" data-exunit="sec">⏱️ 按秒数</button>';
  h+='</div></div>';
  h+='<div class="fg" id="exEmojiFg"'+(ex.type==='cardio'?'':' style="display:none"')+'><label class="fl" for="exEmoji">图标 emoji</label><input class="fi" id="exEmoji" value="'+(ex.emoji||'🏃')+'" placeholder="🏃"></div>';
  h+='<div class="fg" id="exIntensityFg"'+(ex.type==='cardio'?'':' style="display:none"')+'><span class="fl" id="lbl-s-g4">默认强度</span><div class="car-types" id="exIntensitySel" role="group" aria-labelledby="lbl-s-g4"></div></div>';
  h+='<div class="fg" id="exHasDistFg"'+(ex.type==='cardio'?'':' style="display:none"')+' style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="exHasDist"'+(ex.hasDist?' checked':'')+'><label class="fl" for="exHasDist" style="margin:0">有距离统计</label></div>';
  h+='<div class="fg"><label class="fl" for="exDesc">动作描述 <span style="font-weight:400;text-transform:none">（支持 **加粗** #标题 `代码` -列表）</span></label><textarea class="fi" id="exDesc" rows="4" style="resize:vertical;font-size:var(--fs-sm);line-height:1.6" placeholder="可选：记录动作要领、注意事项...">'+(ex.description||'').replace(/</g,'&lt;')+'</textarea></div>';
  h+='<div class="fg" id="exLinkFg"><span class="fl" id="lbl-s-g5">📚 关联动作百科 <span style="font-weight:400;text-transform:none">（可选，提供说明与动图）</span></span><div id="exLinkArea" role="group" aria-labelledby="lbl-s-g5"></div></div>';
  h+='<div class="modal-actions"><button class="m-btn-cancel" id="exCancel">取消</button><button class="m-btn-save" id="exSave">💾 保存</button></div></div>';
  modal.innerHTML=h;void modal;

  var curDsId=ex.dsId||null;

  function renderLinkArea(){
    var area=document.getElementById('exLinkArea');if(!area)return;
    if(curDsId){
      var it=EXD.get(curDsId);
      if(it){
        var m=EXD.mediaUrls(it.img);
        area.innerHTML='<div class="ec" style="margin-top:2px"><div style="display:flex;gap:12px;align-items:center">'
          +'<img src="'+m.primary+'" loading="lazy" onerror="'+(m.fallback?"this.onerror=null;this.src='"+m.fallback+"'":"this.style.display='none'")+'" style="width:64px;height:64px;border-radius:12px;object-fit:cover;background:var(--bg2);border:var(--bw) solid var(--bd);flex-shrink:0">'
          +'<div style="flex:1;min-width:0"><div style="font-weight:700;font-size:var(--fs-md)">'+it.zh+'</div>'
          +'<div style="font-size:var(--fs-2xs);color:var(--text3)">'+it.name+'</div>'
          +'<div style="margin-top:4px">'+tagHtml(it.cat,'cat')+tagHtml(it.eq,'eq')+tagHtml(it.target,'cat')+'</div></div>'
          +'<button class="ec-act" id="exLinkClear" title="解除关联">✕</button></div></div>';
        document.getElementById('exLinkClear').addEventListener('click',function(){curDsId=null;renderLinkArea()});
        return;
      }
    }
    // 未关联: 候选建议 + 手动选择按钮
    var cands=EXD.ready()?EXD.matchCandidates(ex.name||document.getElementById('exName').value||'',4):[];
    var ch=cands.length?'<div style="margin-top:4px;font-size:var(--fs-2xs);color:var(--text3)">按名称匹配的候选:</div>':'';
    cands.forEach(function(c){
      var m=EXD.mediaUrls(c.item.img);
      ch+='<button type="button" data-dsid="'+c.item.id+'" class="ec" style="display:flex;width:100%;text-align:left;gap:12px;margin-top:8px;padding:10px;align-items:center;cursor:pointer">'
        +'<img src="'+m.primary+'" loading="lazy" onerror="'+(m.fallback?"this.onerror=null;this.src='"+m.fallback+"'":"this.style.visibility='hidden'")+'" style="width:56px;height:56px;border-radius:10px;object-fit:cover;background:var(--bg2);border:var(--bw) solid var(--bd);flex-shrink:0">'
        +'<div style="flex:1;min-width:0"><div style="font-size:var(--fs-base);font-weight:700;color:var(--text1)">'+c.item.zh+'</div>'
        +'<div style="font-size:var(--fs-2xs);color:var(--text3);margin-top:2px">'+c.item.name+'</div></div>'
        +'<span style="font-size:var(--fs-3xs);color:var(--purple);border:var(--bw) solid var(--purple);border-radius:var(--rp);padding:2px 7px">'+c.reason+' '+Math.round(c.s)+'</span></button>';
    });
    ch+='<button type="button" id="exLinkPick" class="add-btn" style="margin-top:8px;font-size:var(--fs-sm);padding:8px">🔍 从数据集选择'+(EXD.ready()?' ('+EXD.count()+')':'')+'</button>';
    area.innerHTML=ch;
    area.querySelectorAll('[data-dsid]').forEach(function(b){
      b.addEventListener('click',function(){curDsId=b.dataset.dsid;renderLinkArea()});
    });
    var pick=document.getElementById('exLinkPick');
    if(pick)pick.addEventListener('click',function(){openDsPicker(function(id){if(id){curDsId=id;renderLinkArea();}})});
  }
  renderLinkArea();

  var curType=ex.type;
  var curIntensity=ex.intensity||2;
  modal.querySelectorAll('[data-extype]').forEach(function(b){
    b.addEventListener('click',function(){
      curType=b.dataset.extype;
      modal.querySelectorAll('#exTypeSel .car-type').forEach(function(x){x.classList.toggle('selected',x.dataset.extype===curType)});
      document.getElementById('exRatioFg').style.display=curType==='strength'?'':'none';
      document.getElementById('exEqWeightFg').style.display=curType==='strength'?'':'none';
      document.getElementById('exUnitFg').style.display=curType==='strength'?'':'none';
      document.getElementById('exEmojiFg').style.display=curType==='cardio'?'':'none';
      document.getElementById('exIntensityFg').style.display=curType==='cardio'?'':'none';
      document.getElementById('exHasDistFg').style.display=curType==='cardio'?'flex':'none';
    });
  });
  var intEl=document.getElementById('exIntensitySel');
  INTENSITY_LEVELS.forEach(function(lv){
    var b=document.createElement('button');b.className='car-type'+(lv.id===curIntensity?' selected':'');
    b.textContent=lv.emoji+' '+lv.name;b.dataset.exint=lv.id;
    b.addEventListener('click',function(){curIntensity=parseInt(b.dataset.exint);intEl.querySelectorAll('.car-type').forEach(function(x){x.classList.toggle('selected',parseInt(x.dataset.exint)===curIntensity)})});
    intEl.appendChild(b);
  });
  document.getElementById('exRatioD').addEventListener('click',function(){var v=parseInt(document.getElementById('exRatioVal').textContent);document.getElementById('exRatioVal').textContent=Math.max(10,v-5)});
  document.getElementById('exRatioU').addEventListener('click',function(){var v=parseInt(document.getElementById('exRatioVal').textContent);document.getElementById('exRatioVal').textContent=Math.min(100,v+5)});
  var curUnit=ex.unit||'rep';
  modal.querySelectorAll('[data-exunit]').forEach(function(b){
    b.addEventListener('click',function(){
      curUnit=b.dataset.exunit;
      modal.querySelectorAll('#exUnitSel .car-type').forEach(function(x){x.classList.toggle('selected',x.dataset.exunit===curUnit)});
    });
  });
  document.getElementById('exCancel').addEventListener('click',function(){modal.remove()});
  document.getElementById('exSave').addEventListener('click',function(){
    var name=document.getElementById('exName').value.trim();
    if(!name){toast('请输入名称','e');return}
    var desc=document.getElementById('exDesc').value.trim();
    var list=getExercises();
    var mergeResult=null;
    if(isEdit&&name!==editId){
      // 改名：撞名 → 合并迁移（历史/PR/计划四库联动），否则纯改名
      var exists=list.some(function(x){return x.id===name});
      if(exists&&!confirm('「'+name+'」已存在：\n\n将把「'+editId+'」的历史训练记录、PR（取最大值）与计划引用合并到「'+name+'」，并删除旧动作。\n\n确认合并？'))return;
      mergeResult=renameOrMergeExercise(editId,name);
      if(!mergeResult.ok){toast('原动作不存在，刷新后重试','e');return}
      editId=name;
      list=getExercises();
    }else if(!isEdit&&list.some(function(x){return x.id===name})){
      toast('已存在同名动作','e');return;
    }
    if(curType==='strength'){
      var ratio=parseInt(document.getElementById('exRatioVal').textContent);
      var eqWeightRaw=document.getElementById('exEqWeight').value.trim();
      var eqWeight=eqWeightRaw?parseFloat(eqWeightRaw):null;
      var newEx={id:isEdit?editId:name,name:name,type:'strength',ratio:ratio,intensity:null,emoji:null,hasDist:false,description:desc,eqWeight:eqWeight,unit:curUnit};
    }else{
      var emoji=document.getElementById('exEmoji').value.trim()||'🏃';
      var hasDist=document.getElementById('exHasDist').checked;
      var newEx={id:isEdit?editId:(name),name:name,type:'cardio',ratio:null,intensity:curIntensity,emoji:emoji,hasDist:hasDist,description:desc,eqWeight:null,unit:'rep'};
    }
    // dsId：合并时保留目标动作的关联（若目标已有关联），否则用编辑表单里的
    var effDsId=(mergeResult&&mergeResult.merged&&mergeResult.dstDsId)?mergeResult.dstDsId:curDsId;
    if(effDsId)newEx.dsId=effDsId;
    if(isEdit){
      var idx=list.findIndex(function(x){return x.id===editId});
      if(idx>-1)list[idx]=newEx;
    }else{
      list.push(newEx);
    }
    saveExercises(list);
    modal.remove();
    renderExLibrary();
    if(typeof initCardioTypes==='function')initCardioTypes();
    toast(isEdit?(mergeResult&&mergeResult.merged?'已合并到「'+name+'」':'已更新'):'已添加「'+name+'」','s');
  });
  modal.addEventListener('click',function(e){if(e.target===e.currentTarget)modal.remove()});
}

function delExercise(id){
  var all=getExercises(),idx=-1,obj=null
  all.forEach(function(x,i){if(x.id===id){idx=i;obj=x}})
  saveExercises(all.filter(function(x){return x.id!==id}))
  renderExLibrary()
  if(typeof initCardioTypes==='function')initCardioTypes()
  /* v2.14.35：删除可撤销（30 秒），按原下标插回 */
  if(obj&&typeof showUndoBar==='function'){
    showUndoBar('已删除动作「'+obj.name+'」',function(){
      saveExercises(insertAt(getExercises(),obj,idx))
      renderExLibrary()
      if(typeof initCardioTypes==='function')initCardioTypes()
      if(typeof renderStr==='function')renderStr()
    })
  }else toast('已删除','s')
}

/* ========== DATASET PICKER / ENCYCLOPEDIA OVERLAY ==========
   全屏 overlay 动作百科（裁决 5）。mode='pick' 时点条目回调 dsId 并关闭；
   mode='browse' 纯浏览。分页 50 条 + 触底加载；GIF 点击才播放。 */
var _exdPage=50,_exdShown=50;

function openDsPicker(onPick){
  /* v2.14.36：数据集按需加载 —— 未就绪时先拉，拉到后重开同一个入口（onPick 语义不变） */
  if(typeof EXD!=='undefined'&&!EXD.ready()){
    EXD.load(function(ok){ if(ok)openDsPicker(onPick); else toast('动作百科数据加载失败','e') });
    return;
  }
  var ov=document.createElement('div');ov.className='modal-overlay open';ov.id='dsPicker';
  var h='<div class="modal-sheet" style="height:92vh;max-height:92vh;display:flex;flex-direction:column">'
    +'<div class="modal-handle"></div>'
    +'<div style="display:flex;align-items:center;gap:8px;padding:10px 14px 0"><div class="modal-title" style="flex:1">'+(onPick?'🔗 关联动作':'📖 动作百科')+'</div><button class="ec-act" id="dsClose">✕</button></div>'
    +'<div style="padding:8px 14px"><input class="fi" id="dsKw" placeholder="搜索：中文名 / 英文 / 肌群 / 器械" style="width:100%"></div>'
    +'<div class="car-types" id="dsCatRow" style="padding:6px 14px 0;overflow-x:auto;white-space:nowrap;display:flex;gap:4px;align-items:center"></div>'
    +'<div class="car-types" id="dsEqRow" style="padding:6px 14px 4px;overflow-x:auto;white-space:nowrap;display:flex;gap:4px;align-items:center"></div>'
    +'<div id="dsList" style="flex:1;overflow-y:auto;padding:8px 14px 20px;-webkit-overflow-scrolling:touch"></div>'
    +'<div id="dsDetail" style="display:none"></div>'
    +(EXD.ready()?'':'<div style="padding:20px;text-align:center;color:var(--text3);font-size:var(--fs-xs)">数据集未加载</div>')
    +'</div>';
  ov.innerHTML=h;
  document.body.appendChild(ov);
  if(!(EXD&&EXD.ready()))return;

  var curCat='',curEq='',rows=[];
  function chipHtml(label,val,sel){ return '<button class="car-type'+(sel?' selected':'')+'" data-v="'+val+'">'+label+'</button>'; }

  function renderChips(){
    var cr=document.getElementById('dsCatRow'),er=document.getElementById('dsEqRow');
    cr.innerHTML=chipHtml('全部部位','',!curCat)+EXD.cats().map(function(c){return chipHtml(EXD.getCatLabel(c),c,c===curCat)}).join('');
    er.innerHTML=chipHtml('全部器械','',!curEq)+EXD.eqs().map(function(e2){return chipHtml(EXD.getEqLabel(e2),e2,e2===curEq)}).join('');
    cr.querySelectorAll('.car-type').forEach(function(b){b.addEventListener('click',function(){curCat=b.dataset.v;renderChips();renderList(true)})});
    er.querySelectorAll('.car-type').forEach(function(b){b.addEventListener('click',function(){curEq=b.dataset.v;renderChips();renderList(true)})});
  }

  function cardHtml(it){
    var m=EXD.mediaUrls(it.img);
    return '<button type="button" class="ec" data-id="'+it.id+'" style="display:flex;width:100%;text-align:left;gap:10px;padding:8px;margin-bottom:6px;align-items:center;cursor:pointer">'
      +'<img loading="lazy" src="'+m.primary+'" onerror="'+(m.fallback?"this.onerror=null;this.src='"+m.fallback+"'":"this.style.visibility='hidden'")+'" style="width:52px;height:52px;border-radius:10px;object-fit:cover;background:var(--bg2)">'
      +'<div style="flex:1;min-width:0"><div style="font-size:var(--fs-sm);font-weight:600">'+it.zh+'</div>'
      +'<div style="font-size:var(--fs-3xs);color:var(--text3)">'+it.name+'</div>'
      +'<div style="margin-top:3px">'+tagHtml(it.cat,'cat')+tagHtml(it.eq,'eq')+tagHtml(it.target,'cat')+'</div></div></button>';
  }

  function renderList(reset){
    var box=document.getElementById('dsList');
    if(reset){rows=EXD.search(document.getElementById('dsKw').value.trim(),{cat:curCat,eq:curEq});_exdShown=_exdPage;box.innerHTML='';}
    var slice=rows.slice(_exdShown-_exdPage,_exdShown);
    var frag='';
    slice.forEach(function(r){frag+=cardHtml(EXD.row(r))});
    if(!rows.length&&!reset)frag='<div style="text-align:center;color:var(--text3);font-size:var(--fs-xs);padding:12px">没有更多了</div>';
    else if(!rows.length&&reset)frag='<div class="empty"><span class="empty-e">🔍</span><div class="empty-t">无匹配动作</div></div>';
    box.insertAdjacentHTML('beforeend',frag);
    box.querySelectorAll('[data-id]:not([data-wired])').forEach(function(b){
      b.dataset.wired='1';
      b.addEventListener('click',function(){
        if(onPick){onPick(b.dataset.id);ov.remove();}
        else showDsDetail(b.dataset.id);
      });
    });
    // 触底加载哨兵
    var oldSent=box.querySelector('#dsSentinel');if(oldSent)oldSent.remove();
    if(_exdShown<rows.length){
      var sent=document.createElement('div');sent.id='dsSentinel';sent.style.height='8px';box.appendChild(sent);
      _dsIo&&_dsIo.disconnect();
      _dsIo=new IntersectionObserver(function(es){
        if(es[0].isIntersecting){_exdShown+=_exdPage;renderList(false);}
      },{root:box,rootMargin:'120px'});
      _dsIo.observe(sent);
    }
  }
  var kwTimer=null;
  document.getElementById('dsKw').addEventListener('input',function(){clearTimeout(kwTimer);kwTimer=setTimeout(function(){renderList(true)},180)});
  document.getElementById('dsClose').addEventListener('click',function(){_dsIo&&_dsIo.disconnect();ov.remove()});
  ov.addEventListener('click',function(e){if(e.target===ov){_dsIo&&_dsIo.disconnect();ov.remove()}});
  renderChips();renderList(true);
}
var _dsIo=null;

/* 百科详情视图（browse 模式）：中文说明+分步+肌群+GIF 点击播放 */
function showDsDetail(id){
  var it=EXD.get(id);if(!it)return;
  var list=document.getElementById('dsList'),det=document.getElementById('dsDetail');
  var mi=EXD.mediaUrls(it.img),mg=EXD.mediaUrls(it.gif);
  var secTags=(it.sec||[]).map(function(s){return '<span style="font-size:var(--fs-3xs);background:var(--bg);border:var(--bw) solid var(--bd);padding:1px 7px;border-radius:var(--rp)">'+s+'</span>'}).join(' ');
  var steps=(it.steps||[]).map(function(s,i){return '<li style="font-size:var(--fs-xs);line-height:1.65;margin-bottom:5px">'+s+'</li>'}).join('');
  det.innerHTML='<div style="position:absolute;inset:0;background:var(--bg);z-index:2;overflow-y:auto;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column">'
    +'<div style="display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--bd);position:sticky;top:0;background:var(--bg)"><button class="ec-act" id="dsBack">◀</button><div style="flex:1;min-width:0"><div style="font-weight:700;font-size:var(--fs-base)">'+it.zh+'</div><div style="font-size:var(--fs-3xs);color:var(--text3)">'+it.name+'</div></div></div>'
    +'<div style="flex:1;padding:14px">'
    +'<div id="dsMediaWrap" style="position:relative;width:200px;height:200px;margin:0 auto 12px;background:var(--bg2);border-radius:14px;overflow:hidden;cursor:pointer">'
    +'<img id="dsImg" loading="lazy" src="'+mi.primary+'" onerror="'+(mi.fallback?"this.onerror=null;this.src='"+mi.fallback+"'":"this.style.visibility='hidden'")+'" style="width:100%;height:100%;object-fit:cover">'
    +(it.gif?'<div id="dsPlayOv" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.25)"><span style="background:rgba(0,0,0,.55);color:#fff;font-size:var(--fs-2xs);padding:6px 12px;border-radius:99px">▶ 播放动画</span></div>':'')
    +'</div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px"><span style="font-size:var(--fs-3xs);background:var(--purple);color:#fff;padding:2px 9px;border-radius:var(--rp)">'+it.cat+'</span><span style="font-size:var(--fs-3xs);background:var(--blue);color:#fff;padding:2px 9px;border-radius:var(--rp)">'+it.eq+'</span><span style="font-size:var(--fs-3xs);background:var(--green);color:#fff;padding:2px 9px;border-radius:var(--rp)">🎯 '+it.target+'</span></div>'
    +(it.mg?'<div style="margin-bottom:10px"><div style="font-size:var(--fs-2xs);color:var(--text3);margin-bottom:4px">协同肌群</div>'+secTags+'</div>':'')
    +(it.ins?'<div style="font-size:var(--fs-sm);line-height:1.7;color:var(--text1);white-space:normal;margin-bottom:12px">'+it.ins+'</div>':'')
    +(steps?'<div><div style="font-size:var(--fs-2xs);color:var(--text3);margin-bottom:6px">分步说明</div><ol style="padding-left:18px;margin:0">'+steps+'</ol></div>':'')
    +'</div></div>';
  list.style.display='none';det.style.display='block';
  document.getElementById('dsBack').addEventListener('click',function(){det.style.display='none';list.style.display=''});
  var wrap=document.getElementById('dsMediaWrap');
  if(wrap&&it.gif){
    wrap.addEventListener('click',function playOnce(){
      var mi2=EXD.mediaUrls(it.gif);
      document.getElementById('dsImg').src=mg.primary;
      document.getElementById('dsImg').onerror=function(){if(mg.fallback)this.src=mg.fallback;};
      var ovEl=document.getElementById('dsPlayOv');if(ovEl)ovEl.remove();
      wrap.removeEventListener('click',playOnce);
    });
  }
}

/* ========== SUB-TAB: PLANS ========== */
function renderSettingsPlans(){
  var el=document.getElementById('subPlans');if(!el)return
  var strPlans=getPlans();
  var carPlans=getCardioPlans();
  var h='<h2 class="section-hdr">🏋️ 力量计划 <span style="font-size:var(--fs-3xs);color:var(--text3);font-weight:400">('+strPlans.length+')</span></h2>';
  if(strPlans.length){
    strPlans.forEach(function(p){
      var tags=p.exercises.map(function(e){return e.exercise}).slice(0,5).join('、');
      h+='<div class="ec"><div class="ec-hdr"><div class="ec-ex">📋 '+p.name+'</div><div class="ec-actions"><button class="ec-act" data-a="setEditStrPlan" data-pid="'+p.id+'">✏️</button><button class="ec-act" data-a="setDelStrPlan" data-pid="'+p.id+'">🗑️</button></div></div><div class="ec-prog"><div style="font-size:var(--fs-2xs);color:var(--text2)">'+tags+'</div></div></div>';
    });
  }else{
    /* v2.14.26（评审 P2-7）：空态要有一个动作 —— 原来只有一句「还没有力量计划」，用户不知道下一步去哪。 */
    h+=emptyHtml('📋','还没有力量计划','计划在「训练 → 力量」里创建并执行','<button class="empty-cta" data-a="gotoTraining">去训练 ›</button>','empty-compact');
  }
  h+='<h2 class="section-hdr" style="margin-top:16px">🏃 有氧计划 <span style="font-size:var(--fs-3xs);color:var(--text3);font-weight:400">('+carPlans.length+')</span></h2>';
  if(carPlans.length){
    carPlans.forEach(function(p){
      var tags=p.segments.map(function(s){
        var ct=getAllCardioTypes().find(function(x){return x.id===s.type})||{emoji:'🏃',name:s.type};
        return ct.emoji+s.duration+'min';
      }).slice(0,6);
      h+='<div class="ec"><div class="ec-hdr"><div class="ec-ex">📋 '+p.name+'</div><div class="ec-actions"><button class="ec-act" data-a="setEditCarPlan" data-pid="'+p.id+'">✏️</button><button class="ec-act" data-a="setDelCarPlan" data-pid="'+p.id+'">🗑️</button></div></div><div class="ec-prog"><div style="display:flex;gap:4px;flex-wrap:wrap">'+tags.map(function(n){return '<span style="font-size:var(--fs-2xs);background:var(--bg);color:var(--text2);padding:1px 8px;border-radius:var(--rp);border:var(--bw) solid var(--bd)">'+n+'</span>'}).join('')+'</div></div></div>';
    });
  }else{
    h+=emptyHtml('📋','还没有有氧计划','计划在「训练 → 有氧」里创建并执行','<button class="empty-cta" data-a="gotoCardio">去训练 ›</button>','empty-compact');
  }
  h+='<div style="text-align:center;margin-top:8px;font-size:var(--fs-2xs);color:var(--text3)">计划在训练 Tab 中创建和执行</div>';
  el.innerHTML=h;
}

/* ========== SUB-TAB: GAME MANAGEMENT ========== */
function renderSettingsGame(){
  var el=document.getElementById('subGame');if(!el)return
  var g=getGame();
  var recs=store.get('records')||{};
  var h='<h2 class="section-hdr">🧮 属性计算</h2>';
  h+='<button class="sb-btn" id="setAttrInfoBtn" style="background:var(--bg);color:var(--text);border:var(--bw) solid var(--bd);margin-bottom:16px">🧮 查看属性计算方式</button>';
  /* ===== v2.14.3：图鉴入口（宠物 / 技能 / 天赋，只读）=====
     两个入口指向同一个只读面板（page/codex.js 的 renderCodexPanel）：
       · **主入口**在「挑战 → 🐾 培养」（game-views.js，宠物面板 / 技能面板旁边）——
         图鉴要查的正是那三样东西，放在一起最顺手；
       · **次入口**就是这里「设置 → 🎮 挑战」，理由：本节既有的「属性计算方式 / 属性变更日志」
         同属**查阅类资料**（只读、不影响任何流程），图鉴在这里归档不会混进玩法流程；
         设置页在任何界面都能一步进入（主导航常驻）。
     不新增 tab、不新增路由、不碰培养/战斗/记录三视图的行为。
     渲染在 page/codex.js —— 模块未加载时降级提示，不留死按钮。 */
  h+='<h2 class="section-hdr" style="margin-top:16px">📖 图鉴</h2>';
  h+='<button class="sb-btn" id="setCodexBtn" style="background:var(--bg);color:var(--text);border:var(--bw) solid var(--bd)">📖 查看图鉴（宠物 / 技能 / 天赋）</button>';
  h+='<div style="text-align:center;margin-top:6px;font-size:var(--fs-2xs);color:var(--text3)">只读资料 · 内容全部来自既有定义，不改动任何数值</div>';
  h+='<h2 class="section-hdr">📜 属性变更日志</h2>';
  h+='<button class="sb-btn" id="setAttrLogBtn" style="background:var(--bg);color:var(--text);border:var(--bw) solid var(--bd)">📜 查看日志</button>';
  h+='<h2 class="section-hdr" style="margin-top:16px">🏆 历史最佳记录</h2>';
  h+='<div class="stats-grid">';
  if(recs.maxCleared)h+='<div class="sc"><div class="sc-v" style="font-size:var(--fs-base)">🏁 '+recs.maxCleared+'</div><div class="sc-l">最高关卡</div></div>';
  if(recs.maxAtk)h+='<div class="sc sc-rate"><div class="sc-v">⚔️ '+recs.maxAtk+'</div><div class="sc-l">最高攻击</div></div>';
  if(recs.maxDef)h+='<div class="sc sc-total"><div class="sc-v">🛡️ '+recs.maxDef+'</div><div class="sc-l">最高防御</div></div>';
  if(recs.maxHp)h+='<div class="sc sc-vol"><div class="sc-v">❤️ '+recs.maxHp+'</div><div class="sc-l">最高生命</div></div>';
  h+='</div>';
  h+='<h2 class="section-hdr" style="margin-top:16px">↺ 重置挑战进度</h2>';
  h+='<button class="sb-btn" id="setResetGameBtn" style="background:rgba(var(--danger-rgb),.1);color:var(--red);border:var(--bw) solid rgba(var(--danger-rgb),.3)">↺ 重置挑战进度（已通关 '+g.cleared.length+' 关）</button>';
  el.innerHTML=h;
}

/* ========== SUB-TAB: DATA MANAGEMENT ========== */
function renderSettingsData(){
  var el=document.getElementById('subData');if(!el)return
  var h='<h2 class="section-hdr">📂 数据管理</h2>';
  /* v2.14.26（评审 P2-3）：导出 / 导入 / 云同步 都是次级操作，统一 `.btn-quiet`；
     以前是「一个 plan-card__btn--edit + 一个 sb-btn（品牌描边）」混搭，视觉等级与语义无关。 */
  h+='<div style="display:flex;gap:8px;margin-bottom:12px">';
  h+='<button class="btn-quiet" style="flex:1" id="exportDataBtn">📤 导出数据</button>';
  h+='<button class="btn-quiet" style="flex:1" id="importDataBtn">📥 导入数据</button>';
  h+='</div>';
  h+='<button class="btn-quiet" id="syncDataBtn">🔄 手动云同步</button>';
  /* v2.14.28（评审 P3-4）：原来只写「用于手动备份或跨设备转移数据」，没回答最关键的一句 ——
     导入到底是「合并」还是「覆盖」。真实语义（`store.mergeAll`）是**按键合并**：
     文件里有的键整块覆盖本地同名数据，文件里没提到的键原样保留。文案照此写明，别让人猜。 */
  h+='<div class="data-hint">导出 = 存一份到文件；导入 = <strong>按键合并</strong>：文件里包含的数据整块替换本地同名数据，文件没有的数据保留；云同步 = 与云端双向对齐</div>';
  el.innerHTML=h;
}

/* ========== SETTINGS EVENT HANDLER ========== */
function onSettingsEvent(el,id,act){
  if(id==='exNewBtn'){showExEditor(null);return true}
  if(act==='exEdit'){showExEditor(el.dataset.id);return true}
  if(act==='exDel'){
    if(confirm('确定删除这个动作？历史记录不受影响但不再出现在下拉列表')){delExercise(el.dataset.id)}
    return true}
  if(act==='setEditStrPlan'){openPlanEditor(el.dataset.pid);return true}
  /* v2.14.26（评审 P2-7）：空态 CTA —— 计划在训练 Tab 里创建，直接把用户送到对应子页签 */
  if(act==='gotoTraining'){switchTab('training');switchSub('training','strength');return true}
  if(act==='gotoCardio'){switchTab('training');switchSub('training','cardio');return true}
  if(act==='setDelStrPlan'){
    var ps=getPlans(),pi=-1,pobj=null
    ps.forEach(function(p,i){if(p.id===el.dataset.pid){pi=i;pobj=p}})
    if(pobj&&confirm('确定删除这个计划？')){savePlans(ps.filter(function(p){return p.id!==el.dataset.pid}));renderSettingsPlans();renderStr()
      if(typeof showUndoBar==='function')showUndoBar('已删除计划「'+pobj.name+'」',function(){savePlans(insertAt(getPlans(),pobj,pi));renderSettingsPlans();renderStr()})}
    return true}
  if(act==='setEditCarPlan'){openCardioPlanEditor(el.dataset.pid);return true}
  if(act==='setDelCarPlan'){
    var cps=getCardioPlans(),ci=-1,cobj=null
    cps.forEach(function(p,i){if(p.id===el.dataset.pid){ci=i;cobj=p}})
    if(cobj&&confirm('确定删除这个计划？')){saveCardioPlans(cps.filter(function(p){return p.id!==el.dataset.pid}));renderSettingsPlans();renderCar()
      if(typeof showUndoBar==='function')showUndoBar('已删除计划「'+cobj.name+'」',function(){saveCardioPlans(insertAt(getCardioPlans(),cobj,ci));renderSettingsPlans();renderCar()})}
    return true}
  if(id==='setAttrLogBtn'){showAttrLog();return true}
  if(id==='setAttrInfoBtn'){showAttrInfo();return true}
  /* v2.14.3：图鉴（只读面板，渲染在 page/codex.js） */
  if(id==='setCodexBtn'){
    if(typeof renderCodexPanel==='function'){renderCodexPanel()}
    else{toast('图鉴模块未加载','e')}
    return true}
  if(id==='setResetGameBtn'){
    if(confirm('确定重置所有挑战进度？此操作不可撤销')){
      var g=getGame();g.cleared=[];g.current='1-1';g.attempts={};setGame(g);renderSettingsGame();renderGame();
      toast('挑战进度已重置','s');
    }
    return true}
  if(id==='exportDataBtn'){exportData();return true}
  if(id==='importDataBtn'){importData();return true}
  if(id==='syncDataBtn'){showSyncDialog();return true}
  return false;
}

/* ========== ATTRIBUTE CALC INFO (moved from tab-game.js) ========== */
function showAttrInfo(){
  var info=_attrCalcInfo||{atk:'暂无数据',def:'暂无数据',hp:'暂无数据',vol:0,dur:0,permPenAtk:0,permPenDef:0,permBonusAtk:0,permBonusDef:0,period:{name:'—',volThreshold:2500}};
  var p=info.period||{name:'—',volThreshold:2500};
  var modal=openModal();
  modal.innerHTML='<div class="modal-sheet"><div class="modal-handle"></div><div class="modal-title">🧮 属性计算方式</div>'
    +'<div style="font-size:var(--fs-sm);line-height:1.7;color:var(--text2);padding:4px 0">'
    +'<div style="color:var(--orange);font-weight:700;margin-bottom:4px">⚔️ '+info.atk+'</div>'
    +'<div style="color:var(--blue);font-weight:700;margin-bottom:4px">🛡️ '+info.def+'</div>'
    +'<div style="color:var(--green);font-weight:700;margin-bottom:4px">❤️ '+info.hp+'</div>'
    +'<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--bd);font-size:var(--fs-2xs);color:var(--text3)">'
    +'📊 本月力量容量: '+info.vol+' kg (×动作ratio)<br>'
    +'🏃 本月有氧时长: '+info.dur+' 分钟<br>'
    +'📅 当前旬: '+p.name+' (容量目标 '+p.volThreshold+'kg)<br>'
    +'💡 旬内6天→攻防各+30；容量达标→攻防各+60（达标后永久保留）<br>'
    +'💡 基础属性每月1号归零，累积奖励/惩罚永久保留<br>'
    +((info.permBonusAtk+info.permBonusDef)>0?'🏆 累积奖励: 攻+'+info.permBonusAtk+' 防+'+info.permBonusDef+'<br>':'')
    +((info.permPenAtk+info.permPenDef)>0?'⚠️ 累积惩罚: 攻-'+info.permPenAtk+' 防-'+info.permPenDef+'<br>':'')+'</div></div><div class="modal-actions"><button class="m-btn-cancel" id="attrClose">关闭</button></div></div>';
  void modal;
  document.getElementById('attrClose').addEventListener('click',function(){modal.remove()});
  modal.addEventListener('click',function(e){if(e.target===e.currentTarget)modal.remove()});
}

/* ========== 动作标签：中英翻译 + 多彩 tag ========== */

;
/* ===== pets.js ===== */
/* ============================================
   MyHealth — Pet System Core (M4-1)
   宠物数据结构 + 生命周期（蛋→孵化→成长→成熟）。
   纯逻辑，无 DOM/store。依赖 date-roll.js（时间键/月窗口）。
   时间结算：复用 resolveDateRoll 处理离线多天。
   ============================================ */

/* 宠物常量 */
var PET_CONFIG = {
  hatchDays: 14,          // 孵化期 14 天
  nutritionPerFeed: [0.5, 2],   // 营养液每次 +0.5%~2%
  feedHunger: [10, 15],   // 饲料恢复饥饿 10%~15%
  healthLoss: {           // 饥饿度 → 健康度损失/天
    low: 5,               // < 30% 饥饿 → -5% 健康
    critical: 15,         // < 10% → -15%
    zero: 30              // = 0 → -30%
  },
  growthPerDay: [1, 7],   // 健康达标每天成长 +1%~7%
  matureHungerUse: [20, 35],  // 成熟后每天消耗饥饿 20%~35%
  maxRoster: 4,           // v2.2 WP-A3：每场最多上 4 只（真正的上限常量见 pet-store.js 的 PET_BATTLE_MAX）
  /* v2.1.19 受伤系统：成熟期参战失败 → 50% 几率受伤；受伤期间无法出战。
     恢复进度 injuryHeal 0→100，到 100 解除受伤。
     营养液 每次 +10%~15%（约 7~10 次）；饲料 每次 +4%~5%（约 20~25 次）。 */
  matureInjuryChance: 0.5,
  injuryHeal: { nutrition: [10, 15], feed: [4, 5] }
};

/* 受伤：成熟期战斗失败时调用（概率由调用方判定） */
function injurePet(pet) {
  if (!pet || pet.stage !== 'mature') return { ok: false, reason: '非成熟期' };
  pet.injured = true;
  pet.injuryHeal = 0;
  return { ok: true };
}

/* 治疗受伤：kind = 'nutrition'（营养液）| 'feed'（饲料）
   恢复进度累积到 100 → 解除受伤状态 */
function healPetInjury(pet, kind) {
  if (!pet || !pet.injured) return { ok: false, reason: '未受伤' };
  var cfg = (PET_CONFIG.injuryHeal && PET_CONFIG.injuryHeal[kind]) || PET_CONFIG.injuryHeal.feed;
  var inc = cfg[0] + Math.random() * (cfg[1] - cfg[0]);
  pet.injuryHeal = Math.min(100, (pet.injuryHeal || 0) + inc);
  var healed = false;
  if (pet.injuryHeal >= 100) { pet.injured = false; pet.injuryHeal = 0; healed = true; }
  return { ok: true, inc: inc, progress: pet.injuryHeal, healed: healed };
}

/* 是否可参战：成熟 + 未阵亡 + 未受伤 */
function canPetBattle(pet) {
  return !!pet && pet.stage === 'mature' && !pet.isDead && !pet.injured;
}

/* createPet({speciesId, rarity, name}) → 宠物状态对象（蛋期开始）
   存 store 的结构：dh-pets-v1 下的单个宠物 */
function createPet(spec) {
  spec = spec || {};
  return {
    speciesId: spec.speciesId || 'unknown',
    rarity: spec.rarity || 'R',        // R/SR/SSR/UR
    name: spec.name || '宠物',
    stage: 'egg',                      // 'egg' | 'grow' | 'mature'
    // 蛋期
    hatchProgress: spec.hatchProgress || 0,   // 0-100%
    hatchStartDate: spec.hatchStartDate || dateKey(new Date()),
    // 成长期
    hunger: spec.hunger || 80,         // 0-100 饥饿度（越高越饱）
    health: spec.health || 100,        // 健康度（不可恢复，0 阵亡）
    growth: spec.growth || 0,          // 成长度 0-100+（超100成熟）
    ageDays: spec.ageDays || 0,        // 已养天数
    // 炼化（M4-3）
    refineLevel: spec.refineLevel || 0,
    refineStats: spec.refineStats || {},   // {hp:0,atk:0,def:0,soulAtk:0,soulDef:0,spd:0}
    // 技能（M4-4）
    skillLevels: spec.skillLevels || {},   // {skillId: level}
    // 战斗（M4-5）
    foughtToday: spec.foughtToday || null, // dateKey 记录当天是否参战
    // 状态
    isDead: spec.isDead || false,
    deadAt: spec.deadAt || null,
    lastSettleDate: spec.lastSettleDate || null,  // 上次结算日
    monthlyKey: spec.monthlyKey || null,  // 月度重置键（M4-3）
    /* v2.17：**宠物等级（成熟期经验等级）** —— 旧存档没有这两个字段时
       `petLevelInfo()` 一律按 lv0 / 0 exp 读（优雅退化，不迁移、不补偿）。 */
    level: spec.level || 0,   // 0~PET_LEVEL_MAX（由 exp 推导，属派生缓存）
    exp: spec.exp || 0        // 累计经验（唯一真相；每月清空）
  };
}

/* ============================================================
   v2.17：宠物等级（成熟期经验等级）—— **纯逻辑**，无 DOM、无 store。
   作者规格（逐字）：
     · 「成熟期以上开始累计」；「所需经验 = 目标等级 × 100」
     · 「宠物每级提升 1% 基础属性，即每个属性最多提升 50% 基础值」→ 最高 50 级
     · 「每月清空等级」（幂等键在 pet-store.js 的 `petLevelLedger().monthKey`）
   ⚠️ 与 level-system.js 的**玩家等级**（`LEVEL_TIERS` 的 pet 档）是**两套东西**：
      那个是玩家的等级带来的宠物档加成，这里是宠物自己的经验等级。
   ⚠️ `level` 字段是 `exp` 的**派生缓存**：唯一真相是 `exp`，
      `petLevelSync()` 每次按 exp 重算并回写（因此旧档 / 脏档不会卡在错误等级）。
   ============================================================ */
var PET_LEVEL_MAX = 50;              // 「每只宠物最高 50 级」
var PET_LEVEL_EXP_MULT = 100;        // 「所需经验 = 目标等级 × 100」
var PET_LEVEL_BONUS_PCT = 1;         // 「每级提升 1% 基础属性」
var PET_LEVEL_BONUS_CAP_PCT = PET_LEVEL_MAX * PET_LEVEL_BONUS_PCT;   // 50% 基础值

/* 目标等级 `level` 本级所需经验 = level × 100（lv1=100 / lv2=200 … / lv50=5,000） */
function petLevelStepExp(level) {
  var n = Math.max(0, Math.min(PET_LEVEL_MAX, Math.floor(level || 0)));
  return n * PET_LEVEL_EXP_MULT;
}
/* 从 lv0 累计升到 `level` 所需经验 = Σ_{k=1..level} k×100 = 50·level·(level+1) */
function petLevelCumExp(level) {
  var n = Math.max(0, Math.min(PET_LEVEL_MAX, Math.floor(level || 0)));
  return PET_LEVEL_EXP_MULT * (n * (n + 1) / 2);
}
/* 经验 → 等级（lv0 起；封顶 PET_LEVEL_MAX）。纯函数，不写任何对象。 */
function petLevelFromExp(exp) {
  var e = (typeof exp === 'number' && isFinite(exp)) ? Math.floor(exp) : 0;
  if (e <= 0) return 0;
  var lv = 0;
  /* 上限 50 级 → 循环最多 50 次（用累计公式判定，不做逐级加法累加） */
  while (lv < PET_LEVEL_MAX && e >= petLevelCumExp(lv + 1)) lv++;
  return lv;
}
/* 等级 → 属性加成百分比（lv1 = +1% … lv50 = +50%，封顶） */
function petLevelBonusPct(level) {
  var n = Math.max(0, Math.min(PET_LEVEL_MAX, Math.floor(level || 0)));
  return Math.min(PET_LEVEL_BONUS_CAP_PCT, n * PET_LEVEL_BONUS_PCT);
}
/* 只读视图（**不写 pet**）：等级 / 经验进度 / 加成百分比。
   · `need` = 升到下一级还需的经验（＝ 目标等级 × 100；满级 = 0）
   · `inLevel` = 本级已攒经验（满级 = 0）
   旧存档（缺 level/exp）→ lv0 / 0 exp。 */
function petLevelInfo(pet) {
  var petExp = (pet && typeof pet.exp === 'number' && isFinite(pet.exp)) ? Math.floor(pet.exp) : 0;
  if (petExp < 0) petExp = 0;
  var lv = petLevelFromExp(petExp);
  var maxed = (lv >= PET_LEVEL_MAX);
  /* 满级：累计经验封顶在 lv50 的门槛上（多出来的不累计，等级不再变） */
  var exp = maxed ? petLevelCumExp(PET_LEVEL_MAX) : petExp;
  var base = petLevelCumExp(lv);
  var need = maxed ? 0 : petLevelStepExp(lv + 1);
  var inLevel = maxed ? 0 : Math.max(0, exp - base);
  return {
    level: lv, exp: exp, cumBase: base, inLevel: inLevel, need: need,
    maxed: maxed, maxLevel: PET_LEVEL_MAX,
    pct: (maxed || need <= 0) ? (maxed ? 100 : 0) : Math.min(100, Math.round(inLevel / need * 100)),
    bonusPct: petLevelBonusPct(lv)
  };
}
/* 等级加成（**基础值层**）：levelBonus[k] = floor(基础[k] × 等级%)。
   ⚠️ 只吃 `base`（图鉴＋炼化＋天赋静态，即 createPetUnit 的 base），
      **不参与**稀有度 / 宝珠 / 共鸣的百分比池 —— 由调用点「池算完之后再加」保证
      （见 pet-store.js 的 `applyPetExpLevelBonuses` / `petStatBreakdown`）。
   ⚠️ 纯函数：不写入参、不读存档。速度也在内（「每个属性」＝基础属性六项全含）。 */
function petLevelBonusOf(base, pct) {
  var out = {};
  var b = base || {};
  var p = (typeof pct === 'number' && isFinite(pct)) ? pct : 0;
  if (p < 0) p = 0;
  if (p > PET_LEVEL_BONUS_CAP_PCT) p = PET_LEVEL_BONUS_CAP_PCT;
  var keys = ['hp', 'atk', 'def', 'speed', 'spd', 'soulAtk', 'soulDef'];
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    if (b[k] == null) continue;
    out[k] = Math.floor((b[k] || 0) * p / 100);
  }
  return out;
}
/* 按 exp 重算并回写 `pet.level` / `pet.exp`（**唯一**的等级写入口）。
   满级时把 exp 截到 lv50 门槛（多出来的经验如实丢弃，等级不再变化）。 */
function petLevelSync(pet) {
  if (!pet || typeof pet !== 'object') return { level: 0, exp: 0, leveledUp: false };
  var prev = (typeof pet.level === 'number' && isFinite(pet.level)) ? pet.level : petLevelFromExp(pet.exp);
  var info = petLevelInfo(pet);
  pet.level = info.level;
  pet.exp = info.exp;
  return { level: info.level, exp: info.exp, from: prev, leveledUp: info.level > prev };
}
/* 每月清空（**单只**；幂等闸门在 pet-store.js 的 `petLevelLedger().monthKey`） */
function petLevelResetMonthly(pet) {
  if (!pet || typeof pet !== 'object') return pet;
  pet.level = 0;
  pet.exp = 0;
  return pet;
}

/* 喂营养液（孵化期）：+0.5%~2%，返回进度 */
function feedNutrition(pet) {
  /* v2.1.19：成熟期喂营养液 —— 治疗受伤（10%~15%），不涨孵化进度 */
  if (pet.stage === 'mature') {
    var nh = healPetInjury(pet, 'nutrition');
    if (!nh.ok) return { ok: false, reason: nh.reason };
    return { ok: true, mature: true, injuryHeal: Math.round(nh.progress), healed: nh.healed, inc: nh.inc };
  }
  if (pet.stage !== 'egg') return { ok: false, reason: '非孵化期' };
  var inc = PET_CONFIG.nutritionPerFeed[0] + Math.random() * (PET_CONFIG.nutritionPerFeed[1] - PET_CONFIG.nutritionPerFeed[0]);
  pet.hatchProgress = Math.min(100, pet.hatchProgress + inc);
  normalizePetStage(pet);  // 孵化满 → 立即成长期
  return { ok: true, progress: pet.hatchProgress, inc: inc, stage: pet.stage };
}

/* 喂饲料（成长期）：恢复饥饿 10%~15% */
function feedPet(pet) {
  /* v2.1.19：成熟期也需要喂饲料 —— 恢复饥饿 + 治疗受伤（4%~5%） */
  if (pet.stage === 'mature') {
    var mi = PET_CONFIG.feedHunger[0] + Math.random() * (PET_CONFIG.feedHunger[1] - PET_CONFIG.feedHunger[0]);
    pet.hunger = Math.min(100, pet.hunger + mi);
    var mh = healPetInjury(pet, 'feed');
    return { ok: true, hunger: pet.hunger, inc: mi, mature: true,
             injuryHeal: mh.ok ? Math.round(mh.progress) : null, healed: mh.ok ? mh.healed : false };
  }
  if (pet.stage !== 'grow') return { ok: false, reason: '非成长期' };
  var inc = PET_CONFIG.feedHunger[0] + Math.random() * (PET_CONFIG.feedHunger[1] - PET_CONFIG.feedHunger[0]);
  pet.hunger = Math.min(100, pet.hunger + inc);
  // 喂养加成长度（健康>50 时效果更好，符合"喂养→成长"直觉）
  var growInc = pet.health > 50 ? (2 + Math.random() * 3) : (1 + Math.random() * 2);
  pet.growth = Math.min(100, (pet.growth || 0) + growInc);
  // 成长满 100 → 成熟
  normalizePetStage(pet);  // 成长满 → 立即成熟
  if (pet.growth >= 100) { pet.stage = 'mature'; pet.isDead = false; return { ok: true, hunger: pet.hunger, inc: inc, matured: true, growth: pet.growth }; }
  return { ok: true, hunger: pet.hunger, inc: inc, growth: pet.growth };
}

/* 健康度损失（按饥饿度） */
function healthLossRate(hunger) {
  if (hunger <= 0) return PET_CONFIG.healthLoss.zero;
  if (hunger < 10) return PET_CONFIG.healthLoss.critical;
  if (hunger < 30) return PET_CONFIG.healthLoss.low;
  return 0;
}

/* 单日结算（内部：一次养成的每日更新） */
function settleOneDay(pet, todayKey) {
  var events = [];
  if (pet.stage === 'egg') {
    // 孵化期：进度靠营养液，天数只是倒计时参考
    return { events: events, stage: pet.stage };
  }
  if (pet.stage === 'grow') {
    pet.ageDays++;
    // 饥饿消耗（成长期每天自然消耗？设计未明说，按健康挂钩处理）
    var loss = healthLossRate(pet.hunger);
    pet.health = Math.max(0, pet.health - loss);
    if (pet.health <= 0) {
      pet.isDead = true;
      pet.deadAt = todayKey;
      events.push({ type: 'death', msg: pet.name + ' 健康度归零，阵亡' });
      return { events: events, stage: 'dead' };
    }
    // 成长度：健康达标每天 +1%~7%（健康 > 50% 才算达标）
    if (pet.health > 50) {
      var g = PET_CONFIG.growthPerDay[0] + Math.random() * (PET_CONFIG.growthPerDay[1] - PET_CONFIG.growthPerDay[0]);
      pet.growth += g;
      events.push({ type: 'growth', msg: pet.name + ' 成长度 +' + g.toFixed(1) });
      if (pet.growth >= 100) {
        pet.stage = 'mature';
        events.push({ type: 'mature', msg: '🎉 ' + pet.name + ' 进入成熟期！' });
      }
    }
    return { events: events, stage: pet.stage };
  }
  if (pet.stage === 'mature') {
    pet.ageDays++;
    // 成熟后每天消耗饥饿 20%~35%
    var use = PET_CONFIG.matureHungerUse[0] + Math.random() * (PET_CONFIG.matureHungerUse[1] - PET_CONFIG.matureHungerUse[0]);
    pet.hunger = Math.max(0, pet.hunger - use);
    return { events: events, stage: 'mature' };
  }
  return { events: events, stage: pet.stage };
}

/* 离线多天结算：从 lastSettleDate 到 today，逐天 settle（上限防失控）
   返回 {events, days, stage} */
function settlePet(pet, todayKey, now) {
  if (!pet.lastSettleDate) {
    pet.lastSettleDate = todayKey;
    return { events: [{ type: 'first', msg: pet.name + ' 开始记录' }], days: 0, stage: pet.stage };
  }
  if (pet.isDead) return { events: [], days: 0, stage: 'dead' };

  // 用 date-roll 算天数差（DST 安全）
  var days = daysBetween(pet.lastSettleDate, todayKey);
  if (days <= 0) return { events: [], days: 0, stage: pet.stage };

  var cap = 30;   // 上限 30 天，防极端
  var actual = Math.min(days, cap);
  var events = [];
  var stage = pet.stage;
  for (var i = 0; i < actual; i++) {
    var r = settleOneDay(pet, todayKey);
    events = events.concat(r.events);
    stage = r.stage;
    if (stage === 'dead') break;
  }
  pet.lastSettleDate = todayKey;
  return { events: events, days: actual, stage: stage };
}

/* 孵化检查：蛋期且进度满 → 进入成长期 */
function hatchCheck(pet) {
  if (pet.stage === 'egg' && pet.hatchProgress >= 100) {
    pet.stage = 'grow';
    pet.growth = 0;
    return { hatched: true, msg: '🥚 ' + pet.name + ' 破壳而出！进入成长期' };
  }
  return { hatched: false };
}

/* 实时阶段校正（v2.0.9）：egg→grow（孵化满）/ grow→mature（成长满）
   解决 hatchProgress=100 但 stage 卡在 egg 的 bug（阶段转换原仅在每日结算触发） */
function normalizePetStage(pet) {
  if (pet.stage === 'egg' && pet.hatchProgress >= 100) {
    pet.stage = 'grow';
    if (pet.growth == null) pet.growth = 0;
  }
  if (pet.stage === 'grow' && pet.growth >= 100) {
    pet.stage = 'mature';
  }
  return pet;
}

/* 共鸣加成：按持有总数返回倍率档位 */
function resonanceBonus(totalCount) {
  if (totalCount > 10) return 0.10;
  if (totalCount > 6) return 0.07;
  if (totalCount > 3) return 0.05;
  if (totalCount > 1) return 0.03;
  return 0;
}

/* 月度重置（M4-3 详细实现，这里框架）：
   炼化等级清零、技能减半、材料清空 —— 按 monthly-reset 工具 */
function monthlyResetPet(pet) {
  pet.refineLevel = 0;
  pet.refineStats = {};
  // 技能等级向下取整减半
  for (var k in pet.skillLevels) {
    pet.skillLevels[k] = Math.floor(pet.skillLevels[k] / 2);
  }
  return pet;
}

