          while (!gb.done && t < 300) { groupBattleStep(gb); t++; }
          var tot = allies.reduce(function (a, u) { return a + (u.base.hp || 0); }, 0);
          var lft = allies.reduce(function (a, u) { return a + Math.max(0, u.hp || 0); }, 0);
